/* ================================================================
 * PID 串级控制模块
 *
 * 外环 -- 角度环: 目标航向(yaw) → PID → 角速度(deg/s)
 * 内环 -- 速度环: 目标速度(mm/s) → PID → 电机 duty
 *
 * s_pid[0] = M1 左轮速度环, s_pid[1] = M2 右轮速度环
 * s_angle_pid = 角度环
 * ================================================================ */

static PidController_t s_pid[2];        /* 速度环 */
static PidController_t s_angle_pid;     /* 角度环 */
static float s_target_yaw;              /* 目标航向 (deg) */
static float s_linear_vel;              /* 目标线速度 (mm/s) */
static bool  s_angle_enabled;

/* M1 编码器方向与电机方向相反 */
static const float s_enc_sign[2] = { -1.0f, 1.0f };

/* ---------- 内部辅助 ---------- */
static float Clamp(float v, float lo, float hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

/* 角度差归一化: 输出范围 (-180, 180] */
static float AngleDiff(float target, float current) {
    float d = target - current;
    while (d >  180.0f) d -= 360.0f;
    while (d < -180.0f) d += 360.0f;
    return d;
}

/* ================================================================
 * PID 核心计算
 * ================================================================ */
float PID_Compute(PidController_t *pid, float measurement, float dt) {
    if (!pid->enabled) {
        pid->output = 0.0f;
        return 0.0f;
    }

    float error = pid->setpoint - measurement;

    /* 比例项 */
    float p_out = pid->kp * error;

    /* 积分项 -- 积分分离: 大误差(>300mm/s 或 >90deg)清零 */
    float i_limit_for_this = (pid->integral_limit > 100.0f) ? 300.0f : 90.0f;
    if (fabsf(error) > i_limit_for_this) {
        pid->integral = 0.0f;
    } else {
        pid->integral += error * dt;
        pid->integral = Clamp(pid->integral,
                              -pid->integral_limit, pid->integral_limit);
    }
    float i_out = pid->ki * pid->integral;

    /* 微分项 -- 微分先行 */
    float d_out = 0.0f;
    if (dt > 0.0001f) {
        d_out = pid->kd * (pid->last_measurement - measurement) / dt;
    }
    pid->last_measurement = measurement;
    pid->prev_error = error;

    float out = p_out + i_out + d_out;
    pid->output = Clamp(out, pid->output_min, pid->output_max);
    return pid->output;
}

/* ================================================================
 * 速度环 API
 * ================================================================ */
void PID_Init(void) {
    for (int i = 0; i < 2; i++) {
        PidController_t *p = &s_pid[i];
        p->kp             = PID_DEFAULT_KP;
        p->ki             = PID_DEFAULT_KI;
        p->kd             = PID_DEFAULT_KD;
        p->setpoint       = 0.0f;
