        p->output_max     = PID_DEFAULT_OUT_MAX;
        p->integral_limit = PID_DEFAULT_I_LIMIT;
        p->output         = 0.0f;
        p->last_measurement = 0.0f;
        p->enabled        = false;
    }

    /* 角度环初始化 */
    PidController_t *ap = &s_angle_pid;
    ap->kp             = PID_ANGLE_KP;
    ap->ki             = PID_ANGLE_KI;
    ap->kd             = PID_ANGLE_KD;
    ap->setpoint       = 0.0f;
