#include "bsp.h"

/* ================================================================
 * 巡线模块 - 灰度传感器位置环PID + 丢线续转
 *
 * 架构: 灰度线位置 -> 位置PID -> 角速度 -> 差速分解 -> 速度环PID
 * 丢线: 线丢失时不停车, 沿最后方向续转直到重新找到线(1.5s超时)
 * ================================================================ */

static TraceController_t s_tc;

void Trace_Init(void)
{
    memset(&s_tc, 0, sizeof(s_tc));
    s_tc.kp            = 1.5f;
    s_tc.ki            = 0.05f;
    s_tc.kd            = 0.3f;
    s_tc.setpoint      = 0.0f;
    s_tc.output_limit  = 200.0f;
    s_tc.dead_zone     = 2.0f;
    s_tc.max_angular   = 180.0f;
    s_tc.motor_locked  = true;
    s_tc.enabled       = false;
    printf("Trace init ok (kp=%.2f ki=%.2f kd=%.2f locked)\r\n",
           s_tc.kp, s_tc.ki, s_tc.kd);
}

/* 差速分解: (前进速度, 角速度deg/s) -> 左右轮 mm/s */
static void Trace_ApplyOutput(float speed_mm_s, float angular_deg_s)
{
    float angular_rad_s = angular_deg_s * 3.14159265f / 180.0f;
    float half_wb = CHASSIS_WHEEL_BASE_MM * 0.5f;

    float v_left  = speed_mm_s - angular_rad_s * half_wb;
    float v_right = speed_mm_s + angular_rad_s * half_wb;

    float lim = PID_SPEED_MAX_MM_S;
    if (v_left  >  lim) v_left  =  lim;
    if (v_left  < -lim) v_left  = -lim;
    if (v_right >  lim) v_right =  lim;
    if (v_right < -lim) v_right = -lim;

    PID_SetSetpoint(0, v_left);
    PID_SetSetpoint(1, v_right);
    PID_Enable(0, true);
    PID_Enable(1, true);
}

static uint32_t s_lost_cnt = 0;  /* 丢线计数, 超时1.5s(=150次)则锁定 */

void Trace_Task(void)
{
    if (!s_tc.enabled) return;

    GrayData_t gray;
    if (!Gray_GetData(&gray)) return;

    /* 上电安全锁: 全同时不解锁 */
    if (s_tc.motor_locked) {
        if (gray.all_same) {
            PID_Enable(0, false);
            PID_Enable(1, false);
            Motor_Stop(0);
            Motor_Stop(1);
            return;
        }
        s_tc.motor_locked = false;
        s_tc.integral = 0.0f;
        s_lost_cnt = 0;
        printf("Trace unlocked\r\n");
    }

    /* 丢线处理: 不停车, 沿最后方向续转 */
    if (gray.all_same) {
        s_lost_cnt++;
        if (s_lost_cnt > 150) {  /* 1.5秒超时 */
            s_tc.motor_locked = true;
            PID_Enable(0, false);
            PID_Enable(1, false);
            Motor_Stop(0);
            Motor_Stop(1);
            printf("Trace lost timeout\r\n");
            return;
        }
        /* 沿最后方向转, 减速到50% */
        float last_sign = (s_tc.output > 0.5f) ? 1.0f :
                          ((s_tc.output < -0.5f) ? -1.0f : 1.0f);
        Trace_ApplyOutput((float)s_tc.base_speed * 0.5f, last_sign * 100.0f);
        s_tc.iteration++;
        return;
    }

    /* 找到线, 清零丢线计数 */
    s_lost_cnt = 0;

    /* PID计算 */
    float error = s_tc.setpoint - (float)gray.line_pos;

    if (fabsf(error) < s_tc.dead_zone) error = 0.0f;

    float p_term = s_tc.kp * error;
    s_tc.integral += error * 0.01f;
    float i_limit = s_tc.output_limit * 0.3f;
    if (s_tc.integral >  i_limit) s_tc.integral =  i_limit;
    if (s_tc.integral < -i_limit) s_tc.integral = -i_limit;
    float i_term = s_tc.ki * s_tc.integral;
    float d_term = s_tc.kd * (error - s_tc.last_error) / 0.01f;

    float output = p_term + i_term + d_term;

    if (output >  s_tc.output_limit) output =  s_tc.output_limit;
    if (output < -s_tc.output_limit) output = -s_tc.output_limit;
    if (output != output) output = 0.0f;

    s_tc.error      = error;
    s_tc.last_error = error;
    s_tc.output     = output;
    s_tc.iteration++;

    Trace_ApplyOutput((float)s_tc.base_speed, output);
}

void Trace_Start(int16_t speed_mm_s)
{
    if (speed_mm_s < 0) speed_mm_s = 0;
    if (speed_mm_s > (int16_t)PID_SPEED_MAX_MM_S) speed_mm_s = (int16_t)PID_SPEED_MAX_MM_S;
    s_tc.base_speed   = speed_mm_s;
    s_tc.enabled      = true;
    s_tc.motor_locked = true;
    s_tc.integral     = 0.0f;
    s_tc.last_error   = 0.0f;
    s_lost_cnt        = 0;
    printf("Trace start @ %d mm/s\r\n", speed_mm_s);
}

void Trace_Stop(void)
{
    s_tc.enabled      = false;
    s_tc.motor_locked = true;
    PID_Enable(0, false);
    PID_Enable(1, false);
    Motor_Stop(0);
    Motor_Stop(1);
    printf("Trace stop\r\n");
}

void Trace_Tune(float kp, float ki, float kd)
{
    s_tc.kp = kp;
    s_tc.ki = ki;
    s_tc.kd = kd;
    s_tc.integral = 0.0f;
    printf("Trace tune: kp=%.2f ki=%.2f kd=%.2f\r\n", kp, ki, kd);
}

static void cli_cmd_trace(uint8_t argc, char *argv[])
{
    if (argc < 2) {
        printf("usage: trace start <speed> | stop | tune <kp> <ki> <kd> | status\r\n");
        return;
    }
    if (strcmp(argv[1], "start") == 0) {
        int16_t sp = 200;
        if (argc >= 3) sp = (int16_t)atol(argv[2]);
        Trace_Start(sp);
    }
    else if (strcmp(argv[1], "stop") == 0) {
        Trace_Stop();
    }
    else if (strcmp(argv[1], "tune") == 0 && argc >= 5) {
        Trace_Tune((float)atof(argv[2]), (float)atof(argv[3]), (float)atof(argv[4]));
    }
    else if (strcmp(argv[1], "status") == 0) {
        GrayData_t gray;
        Gray_GetData(&gray);
        printf("trace: en=%d sp=%d err=%.1f out=%.1f lost=%lu pos=%d %s\r\n",
               s_tc.enabled, s_tc.base_speed,
               s_tc.error, s_tc.output,
               (unsigned long)s_lost_cnt, gray.line_pos,
               gray.all_same ? "LOST" : "ok");
    }
    else {
        printf("usage: trace start <speed> | stop | tune <kp> <ki> <kd> | status\r\n");
    }
}

static const DebugCliCommand_t s_trace_cli = {
    "trace", cli_cmd_trace, "trace start <speed> | stop | tune <kp> <ki> <kd> | status"
};

void Trace_RegisterCli(void)
{
    DebugCLI_RegisterCommand(&s_trace_cli);
}

