#include "bsp.h"

/* ================================================================
 * 底盘运动控制模块
 *
 * 状态机: IDLE -> MOVE_DIST/TURN_ABS/TURN_REL/GOTO -> IDLE(done)
 * 航向统一使用 IMU yaw (与角度环同源)
 * 位置使用 Odometry 里程计
 * ================================================================ */

static ChassisStatus_t s_chassis;
static OdomPose_t      s_start_pose;
static int8_t          s_move_dir;

/* ---------- 辅助 ---------- */
static float ClampCh(float v, float lo, float hi) {
    if (v < lo) return lo; if (v > hi) return hi; return v;
}
static float AngleDiffCh(float t, float c) {
    float d = t - c;
    while (d >  180.0f) d -= 360.0f;
    while (d < -180.0f) d += 360.0f;
    return d;
}

/* ================================================================
 * 公共 API
 * ================================================================ */
void Chassis_Init(void)
{
    memset(&s_chassis, 0, sizeof(s_chassis));
    s_chassis.cruise_speed   = CHASSIS_CRUISE_SPEED;
    s_chassis.cruise_angular = CHASSIS_CRUISE_ANGULAR;
    printf("Chassis init ok\r\n");
}

void Chassis_Stop(void)
{
    s_chassis.state = CHASSIS_IDLE;
    s_chassis.done  = true;
    PID_EnableAll(false);
    Motor_StopAll();
    printf("Chassis stop\r\n");
}

void Chassis_MoveDist(float dist_mm)
{
    ImuData_t imu;
    float cur_yaw = 0.0f;
    if (IMU_GetData(&imu)) cur_yaw = imu.ypr[0];

    OdomPose_t cur;
    Odom_GetPose(&cur);
    s_start_pose = cur;

    s_move_dir            = (dist_mm >= 0) ? 1 : -1;
    s_chassis.state       = CHASSIS_MOVE_DIST;
    s_chassis.target_dist = fabsf(dist_mm);
    s_chassis.target_heading = cur_yaw;
    s_chassis.done        = false;

    PID_AngleSetLinearVel(dist_mm >= 0 ? s_chassis.cruise_speed
                                       : -s_chassis.cruise_speed);
    PID_AngleSetYaw(cur_yaw);
    PID_AngleEnable(true);

    printf("Chassis move %.0f mm, hold %.0f deg\r\n", dist_mm, cur_yaw);
}

void Chassis_TurnRel(float delta_deg)
{
    ImuData_t imu;
    float cur_yaw = 0.0f;
    if (IMU_GetData(&imu)) cur_yaw = imu.ypr[0];

    s_chassis.state          = CHASSIS_TURN_REL;
    s_chassis.target_heading = cur_yaw + delta_deg;
    s_chassis.done           = false;

    PID_AngleEnable(true);
    PID_AngleSetLinearVel(0.0f);
    PID_AngleSetYaw(s_chassis.target_heading);

    printf("Chassis turn %.0f deg (rel), target=%.0f\r\n",
           delta_deg, s_chassis.target_heading);
}

void Chassis_TurnAbs(float heading_deg)
{
    s_chassis.state          = CHASSIS_TURN_ABS;
    s_chassis.target_heading = heading_deg;
    s_chassis.done           = false;

    PID_AngleEnable(true);
    PID_AngleSetLinearVel(0.0f);
    PID_AngleSetYaw(heading_deg);

    printf("Chassis turn to %.0f deg (abs)\r\n", heading_deg);
}

void Chassis_GoTo(float x_mm, float y_mm)
{
    OdomPose_t cur;
    Odom_GetPose(&cur);

    s_chassis.state     = CHASSIS_GOTO;
    s_chassis.target_x  = x_mm;
    s_chassis.target_y  = y_mm;
    s_chassis.done      = false;
    s_start_pose        = cur;

    printf("Chassis goto (%.0f, %.0f) from (%.0f, %.0f)\r\n",
           x_mm, y_mm, cur.x_mm, cur.y_mm);
}

bool Chassis_GetStatus(ChassisStatus_t *st)
{
    if (!st) return false;
    *st = s_chassis;
    return true;
}

/* ================================================================
 * 定时任务 (10ms)
 * ================================================================ */
void Chassis_Task(void)
{
    OdomPose_t cur;
    Odom_GetPose(&cur);

    if (s_chassis.state == CHASSIS_IDLE) return;

    switch (s_chassis.state) {

    case CHASSIS_MOVE_DIST: {
        float dx = cur.x_mm - s_start_pose.x_mm;
        float dy = cur.y_mm - s_start_pose.y_mm;
        float traveled = sqrtf(dx * dx + dy * dy);
        float remain   = s_chassis.target_dist - traveled;

        if (remain <= CHASSIS_DIST_TOLERANCE) {
            Chassis_Stop();
            printf("Chassis move done, traveled %.0f mm\r\n", traveled);
            break;
        }

        float spd = s_chassis.cruise_speed;
        if (remain < 100.0f) {
            spd = spd * (remain / 100.0f);
            if (spd < 30.0f) spd = 30.0f;
        }
        spd *= (float)s_move_dir;

        PID_AngleEnable(true);
        PID_AngleSetLinearVel(spd);
        PID_AngleSetYaw(s_chassis.target_heading);
        break;
    }

    case CHASSIS_TURN_ABS:
    case CHASSIS_TURN_REL: {
        /* 用 IMU yaw 判断到位 (与角度环同源) */
        ImuData_t imu_chk;
        float cur_yaw_chk = cur.theta_deg;
        if (IMU_GetData(&imu_chk)) cur_yaw_chk = imu_chk.ypr[0];
        float err = fabsf(AngleDiffCh(s_chassis.target_heading, cur_yaw_chk));

        if (err <= CHASSIS_ANGLE_TOLERANCE) {
            Chassis_Stop();
            printf("Chassis turn done, heading=%.1f\r\n", cur_yaw_chk);
            break;
        }

        float ang_spd = s_chassis.cruise_angular;
        if (err < 30.0f) {
            ang_spd = ang_spd * (err / 30.0f);
            if (ang_spd < 20.0f) ang_spd = 20.0f;
        }

        PID_AngleEnable(true);
        PID_AngleSetLinearVel(0.0f);
        PID_AngleSetYaw(s_chassis.target_heading);
        break;
    }

    case CHASSIS_GOTO: {
        float dx = s_chassis.target_x - cur.x_mm;
        float dy = s_chassis.target_y - cur.y_mm;
        float dist = sqrtf(dx * dx + dy * dy);

        if (dist <= CHASSIS_DIST_TOLERANCE) {
            Chassis_Stop();
            printf("Chassis goto done (%.0f, %.0f)\r\n",
                   cur.x_mm, cur.y_mm);
            break;
        }

        float target_hdg = atan2f(dy, dx) * 57.29578f;

        float spd = s_chassis.cruise_speed;
        if (dist < 200.0f) {
            spd = spd * (dist / 200.0f);
            if (spd < 30.0f) spd = 30.0f;
        }

        PID_AngleEnable(true);
        PID_AngleSetLinearVel(spd);
        PID_AngleSetYaw(target_hdg);
        break;
    }

    default:
        break;
    }
}

/* ================================================================
 * CLI
 * ================================================================ */
static void cli_cmd_chassis(uint8_t argc, char *argv[])
{
    if (argc < 2) {
        printf("usage:\r\n");
        printf("  chassis go <mm>        -- forward mm (-=back)\r\n");
        printf("  chassis turn <deg>     -- relative turn\r\n");
        printf("  chassis yaw <deg>      -- absolute turn\r\n");
        printf("  chassis goto <x> <y>   -- go to (x,y)\r\n");
        printf("  chassis stop | status\r\n");
        return;
    }

    if (strcmp(argv[1], "stop") == 0) {
        Chassis_Stop();
    } else if (strcmp(argv[1], "go") == 0 && argc >= 3) {
        Chassis_MoveDist((float)atof(argv[2]));
    } else if (strcmp(argv[1], "turn") == 0 && argc >= 3) {
        Chassis_TurnRel((float)atof(argv[2]));
    } else if (strcmp(argv[1], "yaw") == 0 && argc >= 3) {
        Chassis_TurnAbs((float)atof(argv[2]));
    } else if (strcmp(argv[1], "goto") == 0 && argc >= 4) {
        Chassis_GoTo((float)atof(argv[2]), (float)atof(argv[3]));
    } else if (strcmp(argv[1], "status") == 0) {
        OdomPose_t cur;
        Odom_GetPose(&cur);
        const char *names[] = {"IDLE","MOVE_DIST","TURN_ABS","TURN_REL","GOTO"};
        printf("state=%s done=%d\r\n",
               names[s_chassis.state], s_chassis.done);
        printf("target: x=%.0f y=%.0f hdg=%.0f dist=%.0f\r\n",
               s_chassis.target_x, s_chassis.target_y,
               s_chassis.target_heading, s_chassis.target_dist);
        printf("current: x=%.0f y=%.0f theta=%.1f\r\n",
               cur.x_mm, cur.y_mm, cur.theta_deg);
        if (s_chassis.state == CHASSIS_GOTO) {
            float dx = s_chassis.target_x - cur.x_mm;
            float dy = s_chassis.target_y - cur.y_mm;
            printf("remain: %.0f mm\r\n", sqrtf(dx*dx + dy*dy));
        }
    } else {
        printf("usage: chassis go|turn|yaw|goto|stop|status\r\n");
    }
}

static const DebugCliCommand_t s_chassis_cli = {
    "chassis", cli_cmd_chassis,
    "chassis go|turn|yaw|goto|stop|status"
};

void Chassis_RegisterCli(void)
{
    DebugCLI_RegisterCommand(&s_chassis_cli);
}

payload.message:
根据我的分析，这个项目**没有专门的直角转弯逻辑**。以下是当前巡线模块的处理方式：

---

## 🔍 当前巡线逻辑分析

### 现有处理方式

在 `trace.c` 中，当遇到**丢线情况**时（`gray.all_same = true`）：

```c
/* 丢线处理: 不停车, 沿最后方向续转 */
if (gray.all_same) {
    s_lost_cnt++;
    if (s_lost_cnt > 150) {  // 1.5秒超时
        // 锁定电机，停止巡线
        s_tc.motor_locked = true;
        Motor_Stop(0);
        Motor_Stop(1);
        return;
    }
    /* 沿最后方向转, 减速到50% */
    float last_sign = (s_tc.output > 0.5f) ? 1.0f : -1.0f;
    Trace_ApplyOutput((float)s_tc.base_speed * 0.5f, last_sign * 100.0f);
    return;
}
```

### 问题

| 场景 | 当前行为 | 问题 |
|------|----------|------|
| **直角弯** | 丢线后沿最后方向续转 | 可能转错方向或转过头 |
| **T形路口** | 同上 | 无法选择正确分支 |
| **十字路口** | 同上 | 完全迷失 |

---

## 💡 如果需要添加直角转弯逻辑

需要增加**多路灰度传感器的模式识别**。以下是实现思路：

### 方案1：基于传感器状态模式识别

```c
// 定义路口类型
typedef enum {
    CROSS_NONE = 0,     // 普通巡线
    CROSS_RIGHT_TURN,   // 右直角弯 (左侧传感器检测到线)
    CROSS_LEFT_TURN,    // 左直角弯 (右侧传感器检测到线)
    CROSS_T_SHAPE,      // T形路口 (左右都检测到)
    CROSS_CROSS,        // 十字路口 (全部检测到)
} CrossType_t;

// 根据8路传感器状态判断
CrossType_t Trace_DetectCross(GrayData_t *gray) {
    // 左侧传感器: ch0, ch1, ch2
    // 右侧传感器: ch5, ch6, ch7
    // 中间传感器: ch3, ch4

    bool left  = gray->raw[0] || gray->raw[1] || gray->raw[2];
    bool right = gray->raw[5] || gray->raw[6] || gray->raw[7];
    bool mid   = gray->raw[3] || gray->raw[4];

    if (left && right && mid) return CROSS_CROSS;
    if (left && right)        return CROSS_T_SHAPE;
    if (left && !right)       return CROSS_LEFT_TURN;
    if (!left && right)       return CROSS_RIGHT_TURN;
    return CROSS_NONE;
}
```

### 方案2：直角转弯状态机

```c
// 在TraceController_t中添加
typedef struct {
    // ... 现有字段 ...
    CrossType_t cross_type;
    uint32_t    cross_timer;
    bool        turning;
} TraceController_t;

// 直角转弯处理
void Trace_HandleRightAngle(TraceController_t *tc, CrossType_t cross) {
    switch (cross) {
    case CROSS_RIGHT_TURN:
        // 右转90度：左轮前进，右轮停止/反转
        tc->turning = true;
        PID_SetSetpoint(0, tc->base_speed);   // 左轮
        PID_SetSetpoint(1, -tc->base_speed * 0.5f);  // 右轮反转
        break;

    case CROSS_LEFT_TURN:
        // 左转90度：右轮前进，左轮停止/反转
        tc->turning = true;
        PID_SetSetpoint(0, -tc->base_speed * 0.5f);  // 左轮反转
        PID_SetSetpoint(1, tc->base_speed);   // 右轮
        break;

    default:
        break;
    }
}
```

### 方案3：结合IMU精确转角

```c
// 使用IMU确保精确转过90度
void Trace_RightAngleTurn(TraceController_t *tc, float delta_deg) {
    ImuData_t imu;
    IMU_GetData(&imu);

    float start_yaw = imu.ypr[0];
    float target_yaw = start_yaw + delta_deg;  // +90 或 -90

    // 切换到角度控制模式
    tc->state = TRACE_TURNING;
    PID_AngleSetYaw(target_yaw);
    PID_AngleSetLinearVel(0.0f);  // 原地转向
    PID_AngleEnable(true);
}
```

---

## 📝 总结

| 功能 | 当前状态 | 建议 |
|------|----------|------|
| **直角弯检测** | ❌ 无 | 需添加传感器模式识别 |
| **直角弯执行** | ❌ 仅丢线续转 | 需添加专用转弯状态机 |
| **转弯精度** | 依赖PID | 可结合IMU提高精度 |
| **路口选择** | ❌ 无 | 需添加决策逻辑 |

如果你需要，我可以帮你**添加直角转弯功能**到 `trace.c` 中。需要考虑：

