/**
 * @file    DX_driver_gpio.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   GPIO 驱动源文件
 */

#include "DX_driver_gpio.h"

/**
 * @brief  GPIO 初始化
 */
void DX_GPIO_Init(GPIO_TypeDef *port, uint16_t pin, DX_GpioMode_t mode)
{
    GPIO_InitTypeDef gpio = {0};
    gpio.Pin = pin;
    gpio.Speed = GPIO_SPEED_FREQ_HIGH;

    switch (mode)
    {
    case DX_GPIO_OUTPUT_PP:
        gpio.Mode = GPIO_MODE_OUTPUT_PP;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_OUTPUT_OD:
        gpio.Mode = GPIO_MODE_OUTPUT_OD;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_INPUT_FLOAT:
        gpio.Mode = GPIO_MODE_INPUT;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_INPUT_PULLUP:
        gpio.Mode = GPIO_MODE_INPUT;
        gpio.Pull = GPIO_PULLUP;
        break;
    case DX_GPIO_INPUT_PULLDOWN:
        gpio.Mode = GPIO_MODE_INPUT;
        gpio.Pull = GPIO_PULLDOWN;
        break;
    case DX_GPIO_ANALOG:
        gpio.Mode = GPIO_MODE_ANALOG;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_AF_PP:
        gpio.Mode = GPIO_MODE_AF_PP;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_AF_OD:
        gpio.Mode = GPIO_MODE_AF_OD;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_IT_RISING:
        gpio.Mode = GPIO_MODE_IT_RISING;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_IT_FALLING:
        gpio.Mode = GPIO_MODE_IT_FALLING;
        gpio.Pull = GPIO_NOPULL;
        break;
    case DX_GPIO_IT_BOTH:
        gpio.Mode = GPIO_MODE_IT_RISING_FALLING;
        gpio.Pull = GPIO_NOPULL;
        break;
    default:
        gpio.Mode = GPIO_MODE_INPUT;
        gpio.Pull = GPIO_NOPULL;
        break;
    }

    /* 使能 GPIO 时钟 */
    if (port == GPIOA) __HAL_RCC_GPIOA_CLK_ENABLE();
    else if (port == GPIOB) __HAL_RCC_GPIOB_CLK_ENABLE();
    else if (port == GPIOC) __HAL_RCC_GPIOC_CLK_ENABLE();
    else if (port == GPIOD) __HAL_RCC_GPIOD_CLK_ENABLE();
    else if (port == GPIOE) __HAL_RCC_GPIOE_CLK_ENABLE();
    else if (port == GPIOF) __HAL_RCC_GPIOF_CLK_ENABLE();
    else if (port == GPIOG) __HAL_RCC_GPIOG_CLK_ENABLE();

    HAL_GPIO_Init(port, &gpio);
}

/**
 * @brief  GPIO 输出高电平
 */
void DX_GPIO_SetHigh(GPIO_TypeDef *port, uint16_t pin)
{
    HAL_GPIO_WritePin(port, pin, GPIO_PIN_SET);
}

/**
 * @brief  GPIO 输出低电平
 */
void DX_GPIO_SetLow(GPIO_TypeDef *port, uint16_t pin)
{
    HAL_GPIO_WritePin(port, pin, GPIO_PIN_RESET);
}

/**
 * @brief  GPIO 翻转输出电平
 */
void DX_GPIO_Toggle(GPIO_TypeDef *port, uint16_t pin)
{
    HAL_GPIO_TogglePin(port, pin);
}

/**
 * @brief  GPIO 读取输入电平
 */
uint8 DX_GPIO_Read(GPIO_TypeDef *port, uint16_t pin)
{
    return (HAL_GPIO_ReadPin(port, pin) == GPIO_PIN_SET) ? 1 : 0;
}

/**
 * @brief  GPIO 输出指定电平
 */
void DX_GPIO_Write(GPIO_TypeDef *port, uint16_t pin, uint8 state)
{
    HAL_GPIO_WritePin(port, pin, state ? GPIO_PIN_SET : GPIO_PIN_RESET);
}
