/**
 * @file    DX_driver_uart.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   UART 驱动源文件
 */

#include "DX_driver_uart.h"

/* 串口句柄数组 */
static UART_HandleTypeDef *s_uart_handles[DX_UART_COUNT] = {
    &huart1, &huart2, &huart3, &huart6
};

/* 接收回调函数数组 */
static DX_UartRxCb_t s_rx_callbacks[DX_UART_COUNT] = {NULL};

/* 接收缓冲区 */
static uint8 s_rx_buf[DX_UART_COUNT];

/**
 * @brief  串口初始化
 */
void DX_UART_Init(DX_UartId_t id, uint32 baud, DX_UartPin_t pin)
{
    if (id >= DX_UART_COUNT) return;

    UART_HandleTypeDef *huart = s_uart_handles[id];
    huart->Init.BaudRate = baud;
    huart->Init.WordLength = UART_WORDLENGTH_8B;
    huart->Init.StopBits = UART_STOPBITS_1;
    huart->Init.Parity = UART_PARITY_NONE;
    huart->Init.Mode = UART_MODE_TX_RX;
    huart->Init.HwFlowCtl = UART_HWCONTROL_NONE;
    huart->Init.OverSampling = UART_OVERSAMPLING_16;

    HAL_UART_Init(huart);
}

/**
 * @brief  串口发送一个字节
 */
void DX_UART_SendByte(DX_UartId_t id, uint8 data)
{
    if (id >= DX_UART_COUNT) return;
    HAL_UART_Transmit(s_uart_handles[id], &data, 1, 100);
}

/**
 * @brief  串口发送缓冲区
 */
void DX_UART_SendBuffer(DX_UartId_t id, const uint8 *buf, uint16 len)
{
    if (id >= DX_UART_COUNT || len == 0) return;
    HAL_UART_Transmit(s_uart_handles[id], (uint8*)buf, len, 1000);
}

/**
 * @brief  串口发送字符串
 */
void DX_UART_SendString(DX_UartId_t id, const char *str)
{
    if (id >= DX_UART_COUNT || str == NULL) return;
    DX_UART_SendBuffer(id, (const uint8*)str, strlen(str));
}

/**
 * @brief  启动串口接收中断
 */
void DX_UART_StartReceiveIT(DX_UartId_t id, DX_UartRxCb_t cb)
{
    if (id >= DX_UART_COUNT) return;
    s_rx_callbacks[id] = cb;
    HAL_UART_Receive_IT(s_uart_handles[id], &s_rx_buf[id], 1);
}

/**
 * @brief  获取串口句柄
 */
UART_HandleTypeDef* DX_UART_GetHandle(DX_UartId_t id)
{
    if (id >= DX_UART_COUNT) return NULL;
    return s_uart_handles[id];
}

/**
 * @brief  UART 接收完成回调 (HAL 库回调)
 */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    DX_UartId_t id = DX_UART_COUNT;

    if (huart->Instance == USART1) id = DX_UART_1;
    else if (huart->Instance == USART2) id = DX_UART_2;
    else if (huart->Instance == USART3) id = DX_UART_3;
    else if (huart->Instance == USART6) id = DX_UART_6;

    if (id < DX_UART_COUNT && s_rx_callbacks[id] != NULL) {
        s_rx_callbacks[id](s_rx_buf[id]);
    }

    /* 重新启动接收 */
    HAL_UART_Receive_IT(huart, &s_rx_buf[id], 1);
}

/* printf 重定向到 USART1 */
int fputc(int ch, FILE *f)
{
    HAL_UART_Transmit(&huart1, (uint8*)&ch, 1, 100);
    return ch;
}
