/**
 * @file    DX_driver_pwm.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   PWM 驱动源文件
 */

#include "DX_driver_pwm.h"

static int16 s_pwm_duty[DX_PWM_CH_COUNT] = {0};

/* PWM 通道映射表 */
typedef struct {
    TIM_HandleTypeDef *htim;
    uint32_t channel;
} PwmMap_t;

static const PwmMap_t s_pwm_map[DX_PWM_CH_COUNT] = {
    {&htim1, TIM_CHANNEL_1},  /* DX_PWM_TIM1_CH1 = PE9  */
    {&htim1, TIM_CHANNEL_2},  /* DX_PWM_TIM1_CH2 = PE11 */
    {&htim1, TIM_CHANNEL_3},  /* DX_PWM_TIM1_CH3 = PE13 */
    {&htim1, TIM_CHANNEL_4},  /* DX_PWM_TIM1_CH4 = PE14 */
    {&htim9, TIM_CHANNEL_1},  /* DX_PWM_TIM9_CH1 */
    {&htim9, TIM_CHANNEL_2},  /* DX_PWM_TIM9_CH2 */
};

void DX_PWM_Init(DX_PwmChannel_t ch, uint32 period) {
    if (ch >= DX_PWM_CH_COUNT) return;
    /* CubeMX 已初始化 TIM, 此处仅启动 PWM */
    HAL_TIM_PWM_Start(s_pwm_map[ch].htim, s_pwm_map[ch].channel);
}

void DX_PWM_Start(DX_PwmChannel_t ch) {
    if (ch < DX_PWM_CH_COUNT)
        HAL_TIM_PWM_Start(s_pwm_map[ch].htim, s_pwm_map[ch].channel);
}

void DX_PWM_Stop(DX_PwmChannel_t ch) {
    if (ch < DX_PWM_CH_COUNT)
        HAL_TIM_PWM_Stop(s_pwm_map[ch].htim, s_pwm_map[ch].channel);
}

void DX_PWM_SetDuty(DX_PwmChannel_t ch, int16 duty) {
    if (ch >= DX_PWM_CH_COUNT) return;
    s_pwm_duty[ch] = duty;
    __HAL_TIM_SET_COMPARE(s_pwm_map[ch].htim, s_pwm_map[ch].channel, (uint16)abs(duty));
}

int16 DX_PWM_GetDuty(DX_PwmChannel_t ch) {
    if (ch >= DX_PWM_CH_COUNT) return 0;
    return s_pwm_duty[ch];
}
