@"
/**
 * @file    DX_device_motor.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   电机设备源文件
 *
 * 控制逻辑:
 *   A=HIGH B=LOW  -> 正转
 *   A=LOW  B=HIGH -> 反转
 *   A=LOW  B=LOW  -> 滑行
 *   A=HIGH B=HIGH -> 刹车
 */

#if DX_USE_MOTOR

#include "DX_device_motor.h"
#include "DX_driver_gpio.h"
#include "DX_driver_pwm.h"

/* 电机引脚映射结构体 */
typedef struct {
    GPIO_TypeDef *port_a;
    uint16_t      pin_a;
    GPIO_TypeDef *port_b;
    uint16_t      pin_b;
} MotorPin_t;

/* 引脚映射表 */
static const MotorPin_t s_motor_pins[DX_MOTOR_COUNT] = {
    {DX_MOTOR1_A_PORT, DX_MOTOR1_A_PIN, DX_MOTOR1_B_PORT, DX_MOTOR1_B_PIN},
    {DX_MOTOR2_A_PORT, DX_MOTOR2_A_PIN, DX_MOTOR2_B_PORT, DX_MOTOR2_B_PIN},
    {DX_MOTOR3_A_PORT, DX_MOTOR3_A_PIN, DX_MOTOR3_B_PORT, DX_MOTOR3_B_PIN},
    {DX_MOTOR4_A_PORT, DX_MOTOR4_A_PIN, DX_MOTOR4_B_PORT, DX_MOTOR4_B_PIN},
};

static DX_MotorState_t s_motor_state[DX_MOTOR_COUNT];
static bool s_motor_enabled = false;

void DX_Motor_Init(void) {
    /* 初始化电机 GPIO */
    for (int i = 0; i < DX_MOTOR_COUNT; i++) {
        DX_GPIO_Init(s_motor_pins[i].port_a, s_motor_pins[i].pin_a, DX_GPIO_OUTPUT_PP);
        DX_GPIO_Init(s_motor_pins[i].port_b, s_motor_pins[i].pin_b, DX_GPIO_OUTPUT_PP);
        DX_GPIO_SetLow(s_motor_pins[i].port_a, s_motor_pins[i].pin_a);
        DX_GPIO_SetLow(s_motor_pins[i].port_b, s_motor_pins[i].pin_b);

        s_motor_state[i].duty = 0;
        s_motor_state[i].direction = DX_MOTOR_DIR_COAST;
        s_motor_state[i].enabled = false;
    }

    s_motor_enabled = true;
    printf("Motor init ok (4 channels)\r\n");
}

void DX_Motor_Enable(void) {
    s_motor_enabled = true;
}

void DX_Motor_Disable(void) {
    s_motor_enabled = false;
    DX_Motor_StopAll();
}

void DX_Motor_SetSpeed(DX_MotorId_t id, int16 speed) {
    if (id >= DX_MOTOR_COUNT || !s_motor_enabled) return;

    /* 限幅 */
    if (speed > (int16)DX_MOTOR_PWM_DUTY_MAX) speed = (int16)DX_MOTOR_PWM_DUTY_MAX;
    if (speed < -(int16)DX_MOTOR_PWM_DUTY_MAX) speed = -(int16)DX_MOTOR_PWM_DUTY_MAX;

    s_motor_state[id].duty = speed;

    /* 设置方向 */
    if (speed > 0) {
        s_motor_state[id].direction = DX_MOTOR_DIR_FORWARD;
        DX_GPIO_SetHigh(s_motor_pins[id].port_a, s_motor_pins[id].pin_a);
        DX_GPIO_SetLow(s_motor_pins[id].port_b, s_motor_pins[id].pin_b);
    } else if (speed < 0) {
        s_motor_state[id].direction = DX_MOTOR_DIR_REVERSE;
        DX_GPIO_SetLow(s_motor_pins[id].port_a, s_motor_pins[id].pin_a);
        DX_GPIO_SetHigh(s_motor_pins[id].port_b, s_motor_pins[id].pin_b);
    } else {
        s_motor_state[id].direction = DX_MOTOR_DIR_COAST;
        DX_GPIO_SetLow(s_motor_pins[id].port_a, s_motor_pins[id].pin_a);
        DX_GPIO_SetLow(s_motor_pins[id].port_b, s_motor_pins[id].pin_b);
    }

    /* M1/M2 使用 PWM, M3/M4 使用 GPIO */
    if (id == DX_MOTOR_1) {
        DX_PWM_SetDuty(DX_PWM_TIM1_CH3, abs(speed));
    } else if (id == DX_MOTOR_2) {
        DX_PWM_SetDuty(DX_PWM_TIM1_CH1, abs(speed));
    }
}

void DX_Motor_Stop(DX_MotorId_t id) {
    DX_Motor_SetSpeed(id, 0);
}

void DX_Motor_StopAll(void) {
    for (int i = 0; i < DX_MOTOR_COUNT; i++) {
        DX_Motor_Stop((DX_MotorId_t)i);
    }
}

void DX_Motor_Brake(DX_MotorId_t id) {
    if (id >= DX_MOTOR_COUNT) return;
    DX_GPIO_SetHigh(s_motor_pins[id].port_a, s_motor_pins[id].pin_a);
    DX_GPIO_SetHigh(s_motor_pins[id].port_b, s_motor_pins[id].pin_b);
