/**
 * @file    DX_device_encoder.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   编码器设备源文件
 *          编码器线数: 13 * 4倍频 * 28减速比 = 1456 counts/rev
 */

#if DX_USE_ENCODER

#include "DX_device_encoder.h"
#include "DX_driver_timer.h"

static int32  s_total_count[DX_ENCODER_ID_COUNT] = {0};
static int16  s_last_count[DX_ENCODER_ID_COUNT] = {0};
static float  s_speed_rpm[DX_ENCODER_ID_COUNT] = {0};
static float  s_speed_mm_s[DX_ENCODER_ID_COUNT] = {0};
static float  s_distance[DX_ENCODER_ID_COUNT] = {0};

/* M1=TIM5, M2=TIM2 */
static const DX_TimerId_t s_enc_timer[DX_ENCODER_ID_COUNT] = {
    DX_TIM_5, DX_TIM_2
};

void DX_Encoder_Init(void) {
    for (int i = 0; i < DX_ENCODER_ID_COUNT; i++) {
        s_total_count[i] = 0;
        s_last_count[i] = 0;
        s_speed_rpm[i] = 0;
        s_speed_mm_s[i] = 0;
        s_distance[i] = 0;
        HAL_TIM_Encoder_Start(DX_TIM_GetHandle(s_enc_timer[i]), TIM_CHANNEL_ALL);
    }
    printf("Encoder init ok (M1=TIM5, M2=TIM2)\r\n");
}

void DX_Encoder_Reset(DX_EncoderId_t id) {
    if (id >= DX_ENCODER_ID_COUNT) return;
    s_total_count[id] = 0;
    s_last_count[id] = 0;
    s_distance[id] = 0;
    DX_TIM_SetCounter(s_enc_timer[id], 0);
}

void DX_Encoder_ResetAll(void) {
    for (int i = 0; i < DX_ENCODER_ID_COUNT; i++) {
        DX_Encoder_Reset((DX_EncoderId_t)i);
    }
}

int32 DX_Encoder_GetCount(DX_EncoderId_t id) {
    if (id >= DX_ENCODER_ID_COUNT) return 0;
    return s_total_count[id];
}

int16 DX_Encoder_UpdateDelta(DX_EncoderId_t id, uint32 sample_ms) {
    if (id >= DX_ENCODER_ID_COUNT) return 0;

    uint16 cnt = (uint16)DX_TIM_GetCounter(s_enc_timer[id]);
    int16 delta = (int16)(cnt - s_last_count[id]);
    s_last_count[id] = cnt;
    s_total_count[id] += delta;

    /* 计算速度 */
    if (sample_ms > 0) {
        float counts_per_sec = (float)delta * 1000.0f / (float)sample_ms;
        s_speed_rpm[id] = counts_per_sec * 60.0f / DX_ENCODER_COUNTS_REV;
        s_speed_mm_s[id] = counts_per_sec * DX_WHEEL_CIRCUM_MM / DX_ENCODER_COUNTS_REV;
    }

    /* 计算距离 */
    s_distance[id] = (float)s_total_count[id] * DX_WHEEL_CIRCUM_MM / DX_ENCODER_COUNTS_REV;

    return delta;
}

float DX_Encoder_GetSpeedRpm(DX_EncoderId_t id) {
    return (id < DX_ENCODER_ID_COUNT) ? s_speed_rpm[id] : 0;
}

float DX_Encoder_GetSpeedMmS(DX_EncoderId_t id) {
    return (id < DX_ENCODER_ID_COUNT) ? s_speed_mm_s[id] : 0;
}

float DX_Encoder_GetDistance(DX_EncoderId_t id) {
    return (id < DX_ENCODER_ID_COUNT) ? s_distance[id] : 0;
}

bool DX_Encoder_GetData(DX_EncoderId_t id, DX_EncoderData_t *data) {
    if (id >= DX_ENCODER_ID_COUNT || data == NULL) return false;
    data->total_count = s_total_count[id];
    data->speed_rpm = s_speed_rpm[id];
    data->speed_mm_s = s_speed_mm_s[id];
    data->distance_mm = s_distance[id];
    return true;
}

void DX_Encoder_Task(void) {
    for (int i = 0; i < DX_ENCODER_ID_COUNT; i++) {
        DX_Encoder_UpdateDelta((DX_EncoderId_t)i, DX_TASK_PERIOD_MS);
    }
}

void DX_Encoder_Test(void) {
    printf("Enc1: %ld %.1fmm/s\r\n", s_total_count[0], s_speed_mm_s[0]);
    printf("Enc2: %ld %.1fmm/s\r\n", s_total_count[1], s_speed_mm_s[1]);
}

#endif /* DX_USE_ENCODER */
