/**
 * @file    DX_device_imu.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   IMU 设备源文件 (QMI8658A + Mahony AHRS)
 */

#if DX_USE_IMU

#include "DX_device_imu.h"
#include "DX_driver_i2c.h"

/* Mahony AHRS 参数 */
#define IMU_STARTUP_KP      4.0f
#define IMU_RUN_KP          1.2f
#define IMU_KI              0.03f
#define IMU_CAL_MIN_SAMPLES 100
#define IMU_CAL_MAX_SAMPLES 1000
#define IMU_DEFAULT_CAL     400

/* 静止检测阈值 */
#define IMU_STILL_ACC_TOL   0.08f
#define IMU_STILL_GYRO_DPS  3.0f

/* 滤波器状态 */
typedef struct {
    float q[4];             /* 四元数 */
    float bias[3];          /* 陀螺仪零偏 */
    float integral[3];      /* 积分项 */
    float cal_sum[3];       /* 校准累加 */
    uint16_t cal_target;    /* 校准目标采样数 */
    uint16_t cal_good;      /* 有效校准数 */
} ImuFilter_t;

static DX_ImuData_t s_imu_data;
static ImuFilter_t s_filter;
static bool s_initialized = false;

/* 内部函数 */
static bool IMU_ReadRaw(float accel[3], float gyro[3], float *temp);
static void MahonyAHRS_Update(float accel[3], float gyro[3], float dt);
static float invSqrt(float x);

void DX_IMU_Init(void) {
    uint8_t whoami = DX_I2C_ReadByte(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_WHO_AM_I);
    if (whoami != DX_IMU_WHO_AM_I_VAL) {
        printf("IMU init failed (WHO_AM_I=0x%02X)\r\n", whoami);
        return;
    }

    /* 软复位 */
    DX_I2C_WriteByte(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_REG_RESET, 0xB0);
    HAL_Delay(100);

    /* 配置: 加速度 ±8g, 陀螺仪 ±2000dps */
    DX_I2C_WriteByte(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_REG_CTRL2, 0x04);  /* Accel ±8g */
    DX_I2C_WriteByte(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_REG_CTRL3, 0x54);  /* Gyro ±2000dps */
    DX_I2C_WriteByte(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_REG_CTRL7, 0x03);  /* Enable Accel + Gyro */

    /* 初始化滤波器 */
    memset(&s_filter, 0, sizeof(s_filter));
    s_filter.q[0] = 1.0f;
    s_filter.cal_target = IMU_DEFAULT_CAL;

    memset(&s_imu_data, 0, sizeof(s_imu_data));
    s_imu_data.is_ready = true;
    s_initialized = true;

    printf("IMU init ok (QMI8658A @ 0x%02X)\r\n", DX_IMU_I2C_ADDR);
}

void DX_IMU_Task(void) {
    if (!s_initialized) return;

    float accel[3], gyro[3], temp;
    if (!IMU_ReadRaw(accel, gyro, &temp)) return;

    s_imu_data.accel[0] = accel[0];
    s_imu_data.accel[1] = accel[1];
    s_imu_data.accel[2] = accel[2];
    s_imu_data.gyro_raw[0] = gyro[0];
    s_imu_data.gyro_raw[1] = gyro[1];
    s_imu_data.gyro_raw[2] = gyro[2];
    s_imu_data.temp_c = temp;

    /* 减去零偏 */
    gyro[0] -= s_filter.bias[0];
    gyro[1] -= s_filter.bias[1];
    gyro[2] -= s_filter.bias[2];
    s_imu_data.gyro[0] = gyro[0];
    s_imu_data.gyro[1] = gyro[1];
    s_imu_data.gyro[2] = gyro[2];

    /* Mahony AHRS 更新 */
    MahonyAHRS_Update(accel, gyro, 0.005f);

    /* 四元数转欧拉角 */
    float q0 = s_filter.q[0], q1 = s_filter.q[1], q2 = s_filter.q[2], q3 = s_filter.q[3];
    s_imu_data.ypr[0] = atan2f(2.0f*(q0*q3 + q1*q2), 1.0f - 2.0f*(q2*q2 + q3*q3)) * DX_RAD_TO_DEG;
    s_imu_data.ypr[1] = asinf(2.0f*(q0*q2 - q3*q1)) * DX_RAD_TO_DEG;
    s_imu_data.ypr[2] = atan2f(2.0f*(q0*q1 + q2*q3), 1.0f - 2.0f*(q1*q1 + q2*q2)) * DX_RAD_TO_DEG;

    s_imu_data.samples++;

    /* 校准处理 */
    if (s_imu_data.is_calibrating) {
        s_filter.cal_sum[0] += s_imu_data.gyro_raw[0];
        s_filter.cal_sum[1] += s_imu_data.gyro_raw[1];
        s_filter.cal_sum[2] += s_imu_data.gyro_raw[2];
        s_imu_data.cal_remain--;

        if (s_imu_data.cal_remain == 0) {
            float n = (float)s_filter.cal_target;
            s_filter.bias[0] = s_filter.cal_sum[0] / n;
            s_filter.bias[1] = s_filter.cal_sum[1] / n;
            s_filter.bias[2] = s_filter.cal_sum[2] / n;
            s_imu_data.is_calibrating = false;
            printf("IMU cal done: bias=[%.2f, %.2f, %.2f]\r\n",
                   s_filter.bias[0], s_filter.bias[1], s_filter.bias[2]);
        }
    }
}

bool DX_IMU_GetData(DX_ImuData_t *data) {
    if (data == NULL) return false;
    *data = s_imu_data;
    return s_imu_data.is_ready;
}

float DX_IMU_GetYaw(void) {
    return s_imu_data.ypr[0];
}

void DX_IMU_StartCalibration(uint16 samples) {
    if (samples < IMU_CAL_MIN_SAMPLES) samples = IMU_CAL_MIN_SAMPLES;
    if (samples > IMU_CAL_MAX_SAMPLES) samples = IMU_CAL_MAX_SAMPLES;

    memset(s_filter.cal_sum, 0, sizeof(s_filter.cal_sum));
    s_filter.cal_target = samples;
    s_imu_data.cal_remain = samples;
    s_imu_data.is_calibrating = true;
    printf("IMU cal start (%d samples)\r\n", samples);
}

void DX_IMU_Reset(void) {
    DX_I2C_WriteByte(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_REG_RESET, 0xB0);
    HAL_Delay(100);
    memset(&s_filter, 0, sizeof(s_filter));
    s_filter.q[0] = 1.0f;
    printf("IMU reset\r\n");
}

void DX_IMU_Test(void) {
    DX_ImuData_t data;
    if (DX_IMU_GetData(&data)) {
        printf("YPR: %.1f %.1f %.1f\r\n", data.ypr[0], data.ypr[1], data.ypr[2]);
    }
}

/* 内部实现 */
static bool IMU_ReadRaw(float accel[3], float gyro[3], float *temp) {
    uint8 buf[14];
    if (!DX_I2C_ReadBuffer(DX_I2C_2, DX_IMU_I2C_ADDR, DX_IMU_REG_TEMP_L, buf, 14)) {
        return false;
    }

    int16_t raw_temp = (int16_t)(buf[1] << 8 | buf[0]);
    int16_t raw_ax = (int16_t)(buf[3] << 8 | buf[2]);
    int16_t raw_ay = (int16_t)(buf[5] << 8 | buf[4]);
    int16_t raw_az = (int16_t)(buf[7] << 8 | buf[6]);
    int16_t raw_gx = (int16_t)(buf[9] << 8 | buf[8]);
    int16_t raw_gy = (int16_t)(buf[11] << 8 | buf[10]);
    int16_t raw_gz = (int16_t)(buf[13] << 8 | buf[12]);

    *temp = raw_temp / 256.0f + 25.0f;

    /* ±8g -> m/s^2 */
    float accel_scale = 8.0f * 9.81f / 32768.0f;
    accel[0] = raw_ax * accel_scale;
    accel[1] = raw_ay * accel_scale;
    accel[2] = raw_az * accel_scale;

    /* ±2000dps -> deg/s */
    float gyro_scale = 2000.0f / 32768.0f;
    gyro[0] = raw_gx * gyro_scale;
    gyro[1] = raw_gy * gyro_scale;
    gyro[2] = raw_gz * gyro_scale;

    return true;
}

static void MahonyAHRS_Update(float accel[3], float gyro[3], float dt) {
    float q0 = s_filter.q[0], q1 = s_filter.q[1], q2 = s_filter.q[2], q3 = s_filter.q[3];
    float ix = s_filter.integral[0], iy = s_filter.integral[1], iz = s_filter.integral[2];

    float ax = accel[0], ay = accel[1], az = accel[2];
    float gx = gyro[0] * DX_DEG_TO_RAD, gy = gyro[1] * DX_DEG_TO_RAD, gz = gyro[2] * DX_DEG_TO_RAD;

    float recipNorm = invSqrt(ax*ax + ay*ay + az*az);
    ax *= recipNorm; ay *= recipNorm; az *= recipNorm;

    float vx = 2.0f*(q1*q3 - q0*q2);
    float vy = 2.0f*(q0*q1 + q2*q3);
    float vz = q0*q0 - q1*q1 - q2*q2 + q3*q3;

    float ex = ay*vz - az*vy;
    float ey = az*vx - ax*vz;
    float ez = ax*vy - ay*vx;

    float kp = (s_imu_data.samples < 100) ? IMU_STARTUP_KP : IMU_RUN_KP;
    ix += IMU_KI * ex * dt;
    iy += IMU_KI * ey * dt;
    iz += IMU_KI * ez * dt;

    gx += kp * ex + ix;
    gy += kp * ey + iy;
    gz += kp * ez + iz;

    q0 += (-q1*gx - q2*gy - q3*gz) * 0.5f * dt;
    q1 += ( q0*gx + q2*gz - q3*gy) * 0.5f * dt;
    q2 += ( q0*gy - q1*gz + q3*gx) * 0.5f * dt;
    q3 += ( q0*gz + q1*gy - q2*gx) * 0.5f * dt;

    recipNorm = invSqrt(q0*q0 + q1*q1 + q2*q2 + q3*q3);
    s_filter.q[0] = q0 * recipNorm;
    s_filter.q[1] = q1 * recipNorm;
    s_filter.q[2] = q2 * recipNorm;
    s_filter.q[3] = q3 * recipNorm;
    s_filter.integral[0] = ix;
    s_filter.integral[1] = iy;
    s_filter.integral[2] = iz;
}

static float invSqrt(float x) {
    float halfx = 0.5f * x;
    float y = x;
    long i = *(long*)&y;
    i = 0x5f3759df - (i>>1);
    y = *(float*)&i;
    y = y * (1.5f - (halfx * y * y));
    return y;
}

#endif /* DX_USE_IMU */
