#define GRAY_AD2_PIN    GPIO_PIN_5
#define GRAY_OUT_PORT   GPIOA
#define GRAY_OUT_PIN    GPIO_PIN_3

/* 传感器权重 */
static const int16_t s_sensor_weights[DX_GRAY_CHANNELS] = {
    -100, -75, -50, -25, 25, 50, 75, 100
};

static DX_GrayData_t s_gray_data;

void DX_Gray_Init(void) {
    /* 初始化 AD0-AD2 为输出 */
    DX_GPIO_Init(GRAY_AD0_PORT, GRAY_AD0_PIN, DX_GPIO_OUTPUT_PP);
    DX_GPIO_Init(GRAY_AD1_PORT, GRAY_AD1_PIN, DX_GPIO_OUTPUT_PP);
    DX_GPIO_Init(GRAY_AD2_PORT, GRAY_AD2_PIN, DX_GPIO_OUTPUT_PP);

    /* 初始化 OUT 为输入 */
    DX_GPIO_Init(GRAY_OUT_PORT, GRAY_OUT_PIN, DX_GPIO_INPUT_PULLUP);

    memset(&s_gray_data, 0, sizeof(s_gray_data));
    s_gray_data.line_on_value = DX_GRAY_LINE_ON_VALUE;

    for (int i = 0; i < DX_GRAY_CHANNELS; i++) {
        s_gray_data.sensor_weights[i] = s_sensor_weights[i];
    }

    printf("Gray init ok (8ch, line_on=%d)\r\n", DX_GRAY_LINE_ON_VALUE);
}

static void Gray_SelectChannel(uint8 ch) {
    DX_GPIO_Write(GRAY_AD0_PORT, GRAY_AD0_PIN, (ch >> 0) & 1);
    DX_GPIO_Write(GRAY_AD1_PORT, GRAY_AD1_PIN, (ch >> 1) & 1);
    DX_GPIO_Write(GRAY_AD2_PORT, GRAY_AD2_PIN, (ch >> 2) & 1);
}

static uint8 Gray_ReadChannel(uint8 ch) {
    Gray_SelectChannel(ch);
    HAL_Delay(1);  /* 等待多路器稳定 */
    return DX_GPIO_Read(GRAY_OUT_PORT, GRAY_OUT_PIN);
}

void DX_Gray_ScanAll(uint8 *buf) {
    for (uint8 i = 0; i < DX_GRAY_CHANNELS; i++) {
        buf[i] = Gray_ReadChannel(i);
    }
}

void DX_Gray_Task(void) {
    DX_Gray_ScanAll(s_gray_data.raw);

    int32 sum = 0;
    int32 weight_sum = 0;
    uint8 match_count = 0;

    for (int i = 0; i < DX_GRAY_CHANNELS; i++) {
        s_gray_data.is_black[i] = (s_gray_data.raw[i] == s_gray_data.line_on_value);

        if (s_gray_data.is_black[i]) {
            sum += s_gray_data.sensor_weights[i];
            match_count++;
        }
    }

    /* 判断是否全部相同(丢线) */
    bool all_same = true;
    for (int i = 1; i < DX_GRAY_CHANNELS; i++) {
        if (s_gray_data.raw[i] != s_gray_data.raw[0]) {
            all_same = false;
            break;
        }
    }
    s_gray_data.all_same = all_same;

    /* 计算线位置 */
    if (match_count > 0 && !all_same) {
        s_gray_data.line_pos = (int16_t)(sum / match_count);
    } else {
        /* 丢线时保持上次位置 */
    }

    s_gray_data.sample_count++;
}

bool DX_Gray_GetData(DX_GrayData_t *data) {
    if (data == NULL) return false;
    *data = s_gray_data;
    return true;
}

void DX_Gray_SetLineOnValue(uint8 val) {
    s_gray_data.line_on_value = val ? 1 : 0;
    printf("Gray line_on_value=%d\r\n", s_gray_data.line_on_value);
}

int16 DX_Gray_GetLinePos(void) {
    return s_gray_data.line_pos;
}

void DX_Gray_Test(void) {
    printf("Gray: ");
    for (int i = 0; i < DX_GRAY_CHANNELS; i++) {
        printf("%d", s_gray_data.raw[i]);
    }
    printf(" pos=%d %s\r\n", s_gray_data.line_pos, 
           s_gray_data.all_same ? "LOST" : "ok");
}

#endif /* DX_USE_GRAYSCALE */
