/**
 * @file    DX_control_pid.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   PID 控制器源文件
 *          串级控制: 角度环(外环) -> 速度环(内环)
 */

#if DX_USE_PID

#include "DX_control_pid.h"
#include "DX_device_encoder.h"
#include "DX_device_imu.h"
#include "DX_device_motor.h"

static DX_PidController_t s_pid[2];        /* 速度环: M1/M2 */
static DX_PidController_t s_angle_pid;     /* 角度环 */
static float s_target_yaw;
static float s_linear_vel;
static bool  s_angle_enabled;

/* M1 编码器方向修正 */
static const float s_enc_sign[2] = { -1.0f, 1.0f };

static float Clamp(float v, float lo, float hi) {
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}

static float AngleDiff(float target, float current) {
    float d = target - current;
    while (d >  180.0f) d -= 360.0f;
    while (d < -180.0f) d += 360.0f;
    return d;
}

float DX_PID_Compute(DX_PidController_t *pid, float measurement, float dt) {
    if (!pid->enabled) {
        pid->output = 0.0f;
        return 0.0f;
    }

    float error = pid->setpoint - measurement;

    /* 比例项 */
    float p_out = pid->kp * error;

    /* 积分项 - 积分分离 */
    float i_limit = (pid->integral_limit > 100.0f) ? 300.0f : 90.0f;
    if (fabsf(error) > i_limit) {
        pid->integral = 0.0f;
    } else {
        pid->integral += error * dt;
        pid->integral = Clamp(pid->integral, -pid->integral_limit, pid->integral_limit);
    }
    float i_out = pid->ki * pid->integral;

    /* 微分项 - 微分先行 */
    float d_out = 0.0f;
    if (dt > 0.0001f) {
        d_out = pid->kd * (pid->last_measurement - measurement) / dt;
    }
    pid->last_measurement = measurement;
    pid->prev_error = error;

    float out = p_out + i_out + d_out;
    pid->output = Clamp(out, pid->output_min, pid->output_max);
    return pid->output;
}

void DX_PID_Init(void) {
    for (int i = 0; i < 2; i++) {
        DX_PidController_t *p = &s_pid[i];
        p->kp = DX_PID_SPEED_KP;
        p->ki = DX_PID_SPEED_KI;
        p->kd = DX_PID_SPEED_KD;
        p->output_min = -DX_PID_SPEED_OUT_MAX;
        p->output_max = DX_PID_SPEED_OUT_MAX;
        p->integral_limit = DX_PID_SPEED_I_LIMIT;
        p->enabled = false;
    }

    DX_PidController_t *ap = &s_angle_pid;
    ap->kp = DX_PID_ANGLE_KP;
    ap->ki = DX_PID_ANGLE_KI;
    ap->kd = DX_PID_ANGLE_KD;
    ap->output_min = -DX_PID_ANGLE_OUT_MAX;
    ap->output_max = DX_PID_ANGLE_OUT_MAX;
    ap->integral_limit = DX_PID_ANGLE_I_LIMIT;
    ap->enabled = true;

    s_target_yaw = 0.0f;
    s_linear_vel = 0.0f;
    s_angle_enabled = false;

    printf("PID init ok (speed x2 + angle cascade)\r\n");
}

void DX_PID_Reset(uint8 id) {
    if (id >= 2) return;
    DX_PidController_t *p = &s_pid[id];
    p->integral = 0.0f;
    p->prev_error = 0.0f;
    p->output = 0.0f;
    p->last_measurement = 0.0f;
}

void DX_PID_SetSetpoint(uint8 id, float sp_mm_s) {
    if (id >= 2) return;
    sp_mm_s = Clamp(sp_mm_s, -DX_PID_SPEED_MAX_MM_S, DX_PID_SPEED_MAX_MM_S);
    s_pid[id].setpoint = sp_mm_s;
    if (fabsf(sp_mm_s) < 0.5f) {
        DX_PID_Reset(id);
        s_pid[id].enabled = false;
        DX_Motor_Stop((DX_MotorId_t)id);
    } else {
        s_pid[id].enabled = true;
    }
}

void DX_PID_SetTunings(uint8 id, float kp, float ki, float kd) {
    if (id >= 2) return;
    s_pid[id].kp = kp;
    s_pid[id].ki = ki;
    s_pid[id].kd = kd;
    DX_PID_Reset(id);
}

void DX_PID_SetOutputLimit(uint8 id, float min, float max) {
    if (id >= 2) return;
    s_pid[id].output_min = min;
    s_pid[id].output_max = max;
}

void DX_PID_Enable(uint8 id, bool en) {
    if (id < 2) s_pid[id].enabled = en;
}

void DX_PID_EnableAll(bool en) {
    for (int i = 0; i < 2; i++) s_pid[i].enabled = en;
    s_angle_enabled = en;
}

void DX_PID_AngleSetYaw(float target_yaw_deg) {
    s_target_yaw = target_yaw_deg;
}

void DX_PID_AngleSetLinearVel(float v_mm_s) {
    s_linear_vel = Clamp(v_mm_s, -DX_PID_SPEED_MAX_MM_S, DX_PID_SPEED_MAX_MM_S);
}

void DX_PID_AngleEnable(bool en) {
    s_angle_enabled = en;
}

void DX_PID_AngleTune(float kp, float ki, float kd) {
    s_angle_pid.kp = kp;
    s_angle_pid.ki = ki;
    s_angle_pid.kd = kd;
    s_angle_pid.integral = 0.0f;
}

DX_PidController_t* DX_PID_GetController(uint8 id) {
    if (id >= 2) return NULL;
    return &s_pid[id];
}

void DX_PID_Task(void) {
    float dt = DX_TASK_PERIOD_MS / 1000.0f;

    /* 角度环 */
    if (s_angle_enabled) {
        float cur_yaw = DX_IMU_GetYaw();
        float yaw_err = AngleDiff(s_target_yaw, cur_yaw);
        float angular_vel = DX_PID_Compute(&s_angle_pid, -yaw_err, dt);

        /* 运动学分解: v + ω -> 左右轮速度 */
        float half_wb = DX_CHASSIS_WHEEL_BASE * 0.5f;
        float w_rad = angular_vel * DX_DEG_TO_RAD;
        float vl = s_linear_vel - w_rad * half_wb;
        float vr = s_linear_vel + w_rad * half_wb;

        DX_PID_SetSetpoint(0, vl);
        DX_PID_SetSetpoint(1, vr);
        s_angle_enabled = true;
    }

    /* 速度环 */
    for (int i = 0; i < 2; i++) {
        DX_PidController_t *p = &s_pid[i];
        if (!p->enabled) continue;

        float speed_mm_s = DX_Encoder_GetSpeedMmS((DX_EncoderId_t)i) * s_enc_sign[i];
        float duty = DX_PID_Compute(p, speed_mm_s, dt);
        if (isnan(duty) || isinf(duty)) duty = 0.0f;
        int16 speed_cmd = (int16)Clamp(duty, -DX_MOTOR_PWM_DUTY_MAX, DX_MOTOR_PWM_DUTY_MAX);
        DX_Motor_SetSpeed((DX_MotorId_t)i, speed_cmd);
    }
}

#endif /* DX_USE_PID */
