/**
 * @file    DX_control_odometry.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   里程计源文件 (差速模型)
 */

#if DX_USE_ODOMETRY

#include "DX_control_odometry.h"
#include "DX_device_encoder.h"
#include "DX_device_imu.h"

static DX_OdomPose_t s_pose;

void DX_Odom_Init(void) {
    memset(&s_pose, 0, sizeof(s_pose));
    printf("Odometry init ok\r\n");
}

void DX_Odom_Reset(void) {
    memset(&s_pose, 0, sizeof(s_pose));
}

void DX_Odom_Task(void) {
    float v_left = DX_Encoder_GetSpeedMmS(DX_ENCODER_M1);
    float v_right = DX_Encoder_GetSpeedMmS(DX_ENCODER_M2);

    s_pose.linear_vel = (v_left + v_right) * 0.5f;
    s_pose.angular_vel = (v_right - v_left) / DX_CHASSIS_WHEEL_BASE * DX_RAD_TO_DEG;

    float theta = s_pose.theta_deg * DX_DEG_TO_RAD;
    s_pose.x_mm += s_pose.linear_vel * cosf(theta) * ODOM_PERIOD_SEC;
    s_pose.y_mm += s_pose.linear_vel * sinf(theta) * ODOM_PERIOD_SEC;

    /* 使用 IMU yaw 作为航向 */
    s_pose.theta_deg = DX_IMU_GetYaw();

    s_pose.tick += DX_TASK_PERIOD_MS;
}

bool DX_Odom_GetPose(DX_OdomPose_t *pose) {
    if (pose == NULL) return false;
    *pose = s_pose;
    return true;
}

#endif /* DX_USE_ODOMETRY */
