/**
 * @file    DX_control_chassis.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   底盘运动控制源文件
 */

#if DX_USE_CHASSIS

#include "DX_control_chassis.h"
#include "DX_control_pid.h"
#include "DX_control_odometry.h"
#include "DX_device_imu.h"
#include "DX_device_motor.h"

static DX_ChassisStatus_t s_chassis;
static DX_OdomPose_t s_start_pose;
static int8_t s_move_dir;

void DX_Chassis_Init(void) {
    memset(&s_chassis, 0, sizeof(s_chassis));
    s_chassis.cruise_speed = 200.0f;
    s_chassis.cruise_angular = 120.0f;
    printf("Chassis init ok\r\n");
}

void DX_Chassis_Stop(void) {
    s_chassis.state = DX_CHASSIS_IDLE;
    s_chassis.done = true;
    DX_PID_EnableAll(false);
    DX_Motor_StopAll();
}

void DX_Chassis_MoveDist(float dist_mm) {
    float cur_yaw = DX_IMU_GetYaw();
    DX_OdomPose_t cur;
    DX_Odom_GetPose(&cur);
    s_start_pose = cur;

    s_move_dir = (dist_mm >= 0) ? 1 : -1;
    s_chassis.state = DX_CHASSIS_MOVE_DIST;
    s_chassis.target_dist = fabsf(dist_mm);
    s_chassis.target_heading = cur_yaw;
    s_chassis.done = false;

    DX_PID_AngleSetLinearVel(dist_mm >= 0 ? s_chassis.cruise_speed : -s_chassis.cruise_speed);
    DX_PID_AngleSetYaw(cur_yaw);
    DX_PID_AngleEnable(true);

    printf("Chassis move %.0f mm\r\n", dist_mm);
}

void DX_Chassis_TurnRel(float delta_deg) {
    float cur_yaw = DX_IMU_GetYaw();
    s_chassis.state = DX_CHASSIS_TURN_REL;
    s_chassis.target_heading = cur_yaw + delta_deg;
    s_chassis.done = false;

    DX_PID_AngleEnable(true);
    DX_PID_AngleSetLinearVel(0.0f);
    DX_PID_AngleSetYaw(s_chassis.target_heading);

    printf("Chassis turn %.0f deg (rel)\r\n", delta_deg);
}

void DX_Chassis_TurnAbs(float heading_deg) {
    s_chassis.state = DX_CHASSIS_TURN_ABS;
    s_chassis.target_heading = heading_deg;
    s_chassis.done = false;

    DX_PID_AngleEnable(true);
    DX_PID_AngleSetLinearVel(0.0f);
    DX_PID_AngleSetYaw(heading_deg);

    printf("Chassis yaw to %.0f deg\r\n", heading_deg);
}

void DX_Chassis_GoTo(float x_mm, float y_mm) {
    DX_OdomPose_t cur;
    DX_Odom_GetPose(&cur);
    s_start_pose = cur;

    s_chassis.state = DX_CHASSIS_GOTO;
    s_chassis.target_x = x_mm;
    s_chassis.target_y = y_mm;
    s_chassis.done = false;

    printf("Chassis goto (%.0f, %.0f)\r\n", x_mm, y_mm);
}

bool DX_Chassis_GetStatus(DX_ChassisStatus_t *st) {
    if (st == NULL) return false;
    *st = s_chassis;
    return true;
}

void DX_Chassis_Task(void) {
    DX_OdomPose_t cur;
    DX_Odom_GetPose(&cur);

    if (s_chassis.state == DX_CHASSIS_IDLE) return;

    switch (s_chassis.state) {
    case DX_CHASSIS_MOVE_DIST: {
        float dx = cur.x_mm - s_start_pose.x_mm;
        float dy = cur.y_mm - s_start_pose.y_mm;
        float traveled = sqrtf(dx*dx + dy*dy);
        float remain = s_chassis.target_dist - traveled;

        if (remain <= 5.0f) {
            DX_Chassis_Stop();
            break;
        }

        float spd = s_chassis.cruise_speed;
        if (remain < 100.0f) spd = spd * (remain / 100.0f);
        if (spd < 30.0f) spd = 30.0f;
        spd *= (float)s_move_dir;

        DX_PID_AngleEnable(true);
        DX_PID_AngleSetLinearVel(spd);
        DX_PID_AngleSetYaw(s_chassis.target_heading);
        break;
    }

    case DX_CHASSIS_TURN_ABS:
    case DX_CHASSIS_TURN_REL: {
        float cur_yaw = DX_IMU_GetYaw();
        float err = fabsf(s_chassis.target_heading - cur_yaw);
        while (err > 180.0f) err = 360.0f - err;

        if (err <= 2.0f) {
            DX_Chassis_Stop();
            break;
        }

        DX_PID_AngleEnable(true);
        DX_PID_AngleSetLinearVel(0.0f);
        DX_PID_AngleSetYaw(s_chassis.target_heading);
        break;
    }

    case DX_CHASSIS_GOTO: {
        float dx = s_chassis.target_x - cur.x_mm;
        float dy = s_chassis.target_y - cur.y_mm;
        float dist = sqrtf(dx*dx + dy*dy);

        if (dist <= 5.0f) {
            DX_Chassis_Stop();
            break;
        }

        float target_hdg = atan2f(dy, dx) * DX_RAD_TO_DEG;
        float spd = s_chassis.cruise_speed;
        if (dist < 200.0f) spd = spd * (dist / 200.0f);
        if (spd < 30.0f) spd = 30.0f;

        DX_PID_AngleEnable(true);
        DX_PID_AngleSetLinearVel(spd);
        DX_PID_AngleSetYaw(target_hdg);
        break;
    }

    default:
        break;
    }
}

#endif /* DX_USE_CHASSIS */
