/**
 * @file    DX_control_trace.c
 * @author  DX_RosRobot Library
 * @date    2026-08-24
 * @brief   巡线控制器源文件
 *          灰度传感器位置环 PID + 丢线续转
 */

#if DX_USE_TRACE

#include "DX_control_trace.h"
#include "DX_control_pid.h"
#include "DX_device_grayscale.h"
#include "DX_device_motor.h"

static DX_TraceController_t s_tc;
static uint32_t s_lost_cnt = 0;

static void Trace_ApplyOutput(float speed_mm_s, float angular_deg_s) {
    float angular_rad_s = angular_deg_s * DX_DEG_TO_RAD;
    float half_wb = DX_CHASSIS_WHEEL_BASE * 0.5f;

    float v_left = speed_mm_s - angular_rad_s * half_wb;
    float v_right = speed_mm_s + angular_rad_s * half_wb;

    v_left = DX_CLAMP(v_left, -DX_PID_SPEED_MAX_MM_S, DX_PID_SPEED_MAX_MM_S);
    v_right = DX_CLAMP(v_right, -DX_PID_SPEED_MAX_MM_S, DX_PID_SPEED_MAX_MM_S);

    DX_PID_SetSetpoint(0, v_left);
    DX_PID_SetSetpoint(1, v_right);
    DX_PID_Enable(0, true);
    DX_PID_Enable(1, true);
}

void DX_Trace_Init(void) {
    memset(&s_tc, 0, sizeof(s_tc));
    s_tc.kp = DX_PID_TRACE_KP;
    s_tc.ki = DX_PID_TRACE_KI;
    s_tc.kd = DX_PID_TRACE_KD;
    s_tc.output_limit = DX_PID_TRACE_OUT_MAX;
    s_tc.dead_zone = DX_PID_TRACE_DEAD_ZONE;
    s_tc.max_angular = 180.0f;
    s_tc.motor_locked = true;
    s_tc.enabled = false;

    printf("Trace init ok (kp=%.2f ki=%.2f kd=%.2f)\r\n", s_tc.kp, s_tc.ki, s_tc.kd);
}

void DX_Trace_Task(void) {
    if (!s_tc.enabled) return;

    DX_GrayData_t gray;
    if (!DX_Gray_GetData(&gray)) return;

    /* 安全锁: 全相同时不解锁 */
    if (s_tc.motor_locked) {
        if (gray.all_same) {
            DX_PID_Enable(0, false);
            DX_PID_Enable(1, false);
            DX_Motor_Stop(DX_MOTOR_1);
            DX_Motor_Stop(DX_MOTOR_2);
            return;
        }
        s_tc.motor_locked = false;
        s_tc.integral = 0.0f;
        s_lost_cnt = 0;
        printf("Trace unlocked\r\n");
    }

    /* 丢线处理 */
    if (gray.all_same) {
        s_lost_cnt++;
        if (s_lost_cnt > 150) {  /* 1.5秒超时 */
            s_tc.motor_locked = true;
            DX_PID_Enable(0, false);
            DX_PID_Enable(1, false);
            DX_Motor_Stop(DX_MOTOR_1);
            DX_Motor_Stop(DX_MOTOR_2);
            printf("Trace lost timeout\r\n");
            return;
        }
        /* 沿最后方向续转 */
        float last_sign = (s_tc.output > 0.5f) ? 1.0f : ((s_tc.output < -0.5f) ? -1.0f : 1.0f);
        Trace_ApplyOutput((float)s_tc.base_speed * 0.5f, last_sign * 100.0f);
        s_tc.iteration++;
        return;
    }

    s_lost_cnt = 0;

    /* PID 计算 */
    float error = s_tc.setpoint - (float)gray.line_pos;
    if (fabsf(error) < s_tc.dead_zone) error = 0.0f;

    float p_term = s_tc.kp * error;
    s_tc.integral += error * 0.01f;
    float i_limit = s_tc.output_limit * 0.3f;
    s_tc.integral = DX_CLAMP(s_tc.integral, -i_limit, i_limit);
    float i_term = s_tc.ki * s_tc.integral;
    float d_term = s_tc.kd * (error - s_tc.last_error) / 0.01f;

    float output = p_term + i_term + d_term;
    output = DX_CLAMP(output, -s_tc.output_limit, s_tc.output_limit);
    if (output != output) output = 0.0f;  /* NaN check */

    s_tc.error = error;
    s_tc.last_error = error;
    s_tc.output = output;
    s_tc.iteration++;

    Trace_ApplyOutput((float)s_tc.base_speed, output);
}

void DX_Trace_Start(int16 speed_mm_s) {
    if (speed_mm_s < 0) speed_mm_s = 0;
    if (speed_mm_s > (int16)DX_PID_SPEED_MAX_MM_S) speed_mm_s = (int16)DX_PID_SPEED_MAX_MM_S;

    s_tc.base_speed = speed_mm_s;
    s_tc.enabled = true;
    s_tc.motor_locked = true;
    s_tc.integral = 0.0f;
    s_tc.last_error = 0.0f;
    s_lost_cnt = 0;

    printf("Trace start @ %d mm/s\r\n", speed_mm_s);
}

void DX_Trace_Stop(void) {
    s_tc.enabled = false;
    s_tc.motor_locked = true;
    DX_PID_Enable(0, false);
    DX_PID_Enable(1, false);
    DX_Motor_Stop(DX_MOTOR_1);
    DX_Motor_Stop(DX_MOTOR_2);
    printf("Trace stop\r\n");
}

void DX_Trace_Tune(float kp, float ki, float kd) {
    s_tc.kp = kp;
    s_tc.ki = ki;
    s_tc.kd = kd;
    s_tc.integral = 0.0f;
    printf("Trace tune: kp=%.2f ki=%.2f kd=%.2f\r\n", kp, ki, kd);
}

#endif /* DX_USE_TRACE */
