    if (argc < 2) {
        printf("usage: led on|off|toggle\r\n");
        return;
    }
    if (strcmp(argv[1], "on") == 0) DX_LED_On();
    else if (strcmp(argv[1], "off") == 0) DX_LED_Off();
    else if (strcmp(argv[1], "toggle") == 0) DX_LED_Toggle();
    else printf("usage: led on|off|toggle\r\n");
}
static const DX_CliCommand_t s_led_cmd = {
    "led", cli_led, "led on|off|toggle"
};
#endif

/* 内置命令: motor */
#if DX_USE_MOTOR
static void cli_motor(uint8 argc, char *argv[]) {
    if (argc < 2) {
        printf("usage: motor set <1-4> <speed> | stop | state\r\n");
        return;
    }
    if (strcmp(argv[1], "set") == 0 && argc >= 4) {
        int id = atoi(argv[2]) - 1;
        int16 spd = (int16)atoi(argv[3]);
        if (id >= 0 && id < 4) DX_Motor_SetSpeed((DX_MotorId_t)id, spd);
    } else if (strcmp(argv[1], "stop") == 0) {
        DX_Motor_StopAll();
    } else if (strcmp(argv[1], "state") == 0) {
        for (int i = 0; i < 4; i++) DX_Motor_PrintState((DX_MotorId_t)i);
    }
}
static const DX_CliCommand_t s_motor_cmd = {
    "motor", cli_motor, "motor set <id> <speed> | stop | state"
};
#endif

/* 内置命令: enc */
#if DX_USE_ENCODER
static void cli_enc(uint8 argc, char *argv[]) {
    if (argc < 2) {
        printf("usage: enc state | reset\r\n");
        return;
    }
    if (strcmp(argv[1], "state") == 0) {
        DX_Encoder_Test();
    } else if (strcmp(argv[1], "reset") == 0) {
        DX_Encoder_ResetAll();
        printf("Encoder reset\r\n");
    }
}
static const DX_CliCommand_t s_enc_cmd = {
    "enc", cli_enc, "enc state | reset"
};
#endif

/* 内置命令: imu */
#if DX_USE_IMU
static void cli_imu(uint8 argc, char *argv[]) {
    if (argc < 2) {
        printf("usage: imu raw | ypr | cal | reset\r\n");
        return;
    }
    if (strcmp(argv[1], "raw") == 0 || strcmp(argv[1], "ypr") == 0) {
        DX_IMU_Test();
    } else if (strcmp(argv[1], "cal") == 0) {
        DX_IMU_StartCalibration(400);
    } else if (strcmp(argv[1], "reset") == 0) {
