        else DX_PID_AngleSetYaw(DX_IMU_GetYaw());
        DX_PID_AngleEnable(true);
        printf("go: v=%.0f mm/s\r\n", v);
    } else if (strcmp(argv[1], "yaw") == 0 && argc >= 3) {
        DX_PID_AngleSetLinearVel(0.0f);
        DX_PID_AngleSetYaw((float)atof(argv[2]));
        DX_PID_AngleEnable(true);
        printf("yaw target: %.0f deg\r\n", (float)atof(argv[2]));
    } else if (strcmp(argv[1], "stop") == 0) {
        DX_PID_EnableAll(false);
        DX_Motor_StopAll();
        printf("PID stop\r\n");
