#if DX_USE_CHASSIS
static void cli_chassis(uint8 argc, char *argv[]) {
    if (argc < 2) {
        printf("usage: chassis go|turn|yaw|goto|stop|status\r\n");
        return;
    }
    if (strcmp(argv[1], "go") == 0 && argc >= 3) {
        DX_Chassis_MoveDist((float)atof(argv[2]));
    } else if (strcmp(argv[1], "turn") == 0 && argc >= 3) {
        DX_Chassis_TurnRel((float)atof(argv[2]));
    } else if (strcmp(argv[1], "yaw") == 0 && argc >= 3) {
        DX_Chassis_TurnAbs((float)atof(argv[2]));
    } else if (strcmp(argv[1], "goto") == 0 && argc >= 4) {
        DX_Chassis_GoTo((float)atof(argv[2]), (float)atof(argv[3]));
    } else if (strcmp(argv[1], "stop") == 0) {
        DX_Chassis_Stop();
    } else if (strcmp(argv[1], "status") == 0) {
        DX_ChassisStatus_t st;
        DX_Chassis_GetStatus(&st);
        printf("state=%d done=%d\r\n", st.state, st.done);
    }
}
static const DX_CliCommand_t s_chassis_cmd = {
    "chassis", cli_chassis, "chassis go|turn|yaw|goto|stop|status"
};
#endif

/* 内置命令: trace */
#if DX_USE_TRACE
static void cli_trace(uint8 argc, char *argv[]) {
    if (argc < 2) {
        printf("usage: trace start <speed> | stop | tune <kp> <ki> <kd>\r\n");
        return;
    }
    if (strcmp(argv[1], "start") == 0) {
        int16 sp = (argc >= 3) ? (int16)atoi(argv[2]) : 200;
        DX_Trace_Start(sp);
    } else if (strcmp(argv[1], "stop") == 0) {
        DX_Trace_Stop();
    } else if (strcmp(argv[1], "tune") == 0 && argc >= 5) {
        DX_Trace_Tune((float)atof(argv[2]), (float)atof(argv[3]), (float)atof(argv[4]));
    }
}
static const DX_CliCommand_t s_trace_cmd = {
    "trace", cli_trace, "trace start|stop|tune"
};
#endif

void DX_CLI_Init(void) {
    s_cmd_count = 0;
    s_line_pos = 0;
    s_line_ready = false;

    DX_CLI_RegisterCommand(&s_help_cmd);
#if DX_USE_LED
    DX_CLI_RegisterCommand(&s_led_cmd);
#endif
#if DX_USE_MOTOR
    DX_CLI_RegisterCommand(&s_motor_cmd);
#endif
#if DX_USE_ENCODER
    DX_CLI_RegisterCommand(&s_enc_cmd);
#endif
#if DX_USE_IMU
    DX_CLI_RegisterCommand(&s_imu_cmd);
#endif
#if DX_USE_GRAYSCALE
    DX_CLI_RegisterCommand(&s_gray_cmd);
#endif
#if DX_USE_PID
    DX_CLI_RegisterCommand(&s_pid_cmd);
#endif
#if DX_USE_CHASSIS
    DX_CLI_RegisterCommand(&s_chassis_cmd);
#endif
#if DX_USE_TRACE
    DX_CLI_RegisterCommand(&s_trace_cmd);
#endif

    printf("CLI init ok (%d commands)\r\n", s_cmd_count);
}

bool DX_CLI_RegisterCommand(const DX_CliCommand_t *cmd) {
    if (s_cmd_count >= DX_CLI_MAX_COMMANDS || cmd == NULL) return false;
    s_commands[s_cmd_count++] = cmd;
    return true;
}

void DX_CLI_RxByteFromISR(uint8 byte) {
    if (s_line_ready) return;

    if (byte == '\r' || byte == '\n') {
        if (s_line_pos > 0) {
            s_line_buf[s_line_pos] = '\0';
            s_line_ready = true;
        }
    } else if (byte == '\b' || byte == 0x7F) {
        if (s_line_pos > 0) s_line_pos--;
    } else {
        if (s_line_pos < DX_CLI_LINE_SIZE - 1) {
            s_line_buf[s_line_pos++] = (char)byte;
        }
    }
}

static void CLI_Execute(char *line) {
    char *argv[DX_CLI_MAX_ARGS];
    uint8 argc = 0;

    char *token = strtok(line, " ");
    while (token != NULL && argc < DX_CLI_MAX_ARGS) {
        argv[argc++] = token;
        token = strtok(NULL, " ");
    }

    if (argc == 0) return;

    for (int i = 0; i < s_cmd_count; i++) {
        if (strcmp(argv[0], s_commands[i]->name) == 0) {
            s_commands[i]->handler(argc, argv);
            DX_CLI_PrintPrompt();
            return;
        }
    }

    printf("Unknown command: %s\r\n", argv[0]);
    DX_CLI_PrintPrompt();
}

void DX_CLI_Process(void) {
    if (s_line_ready) {
        CLI_Execute(s_line_buf);
        s_line_pos = 0;
        s_line_ready = false;
    }
}

void DX_CLI_PrintPrompt(void) {
    printf("\r\n> ");
}

#endif /* DX_USE_DEBUG_CLI */
