payload.message:
## 🎓 协作式时间片轮询调度详解

---

### 一、核心思想

**协作式**：任务主动让出 CPU（不会被强制打断）

**时间片**：按时间分配任务执行机会

**轮询**：主循环不断检查"时间到了没"

---

### 二、最简单的模型

```c
while (1) {
    if (该执行任务A了) 执行任务A();
    if (该执行任务B了) 执行任务B();
    if (该执行任务C了) 执行任务C();
}
```

就像一个**永不停止的传送带**，任务按顺序上去执行。

---

### 三、时间管理原理

#### 3.1 系统时钟

```c
// STM32 的 HAL 库提供一个毫秒计数器
uint32_t HAL_GetTick();  // 返回系统启动后的毫秒数
// 0, 1, 2, 3, ... 一直往上加
```

#### 3.2 判断"时间到了"

```c
// 记录上次执行时间
uint32_t last_time = 0;

while (1) {
    uint32_t now = HAL_GetTick();

    // 检查是否过了 10ms
    if (now - last_time >= 10) {
        last_time = now;  // 更新时间戳
        DoSomething();    // 执行任务
    }
}
```

#### 3.3 为什么用 `now - last_time >= 10`？

**防止溢出问题**：

```c
// 假设计数器是 uint32_t，最大值 4294967295
// 当 now=10, last_time=4294967290 时
// now - last_time = 10 - 4294967290 = 16（无符号溢出，结果正确！）

// 如果用 now > last_time + 10
// last_time + 10 会溢出，判断出错！
```

---

### 四、完整调度框架

```c
// 任务时间戳
uint32_t last_task1 = 0;
uint32_t last_task2 = 0;
uint32_t last_task3 = 0;

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    // ... 外设初始化 ...

    while (1)
    {
        uint32_t now = HAL_GetTick();

        // ========== 任务1：10ms 周期 ==========
        if (now - last_task1 >= 10) {
            last_task1 = now;
            Encoder_Task();    // 编码器采样
            PID_Task();        // PID 计算
        }

        // ========== 任务2：5ms 周期 ==========
        if (now - last_task2 >= 5) {
            last_task2 = now;
            IMU_Task();        // IMU 更新
        }

        // ========== 任务3：100ms 周期 ==========
        if (now - last_task3 >= 100) {
            last_task3 = now;
            LED_Task();        // LED 闪烁
            CLI_Task();        // 命令行处理
        }

        // ========== 每次循环都执行 ==========
        IWDG_Feed();  // 喂狗
    }
}
```

---

### 五、执行时序图

```
时间轴 (ms)：
0    5    10   15   20   25   30   35   40
|    |    |    |    |    |    |    |    |
├────┼────┼────┼────┼────┼────┼────┼────┤
│    │    │    │    │    │    │    │    │
│    │ IMU│Task│    │ IMU│Task│    │ IMU│
│    │    │1+2 │    │    │1+2 │    │    │
│    │    │    │    │    │    │    │    │
└────┴────┴────┴────┴────┴────┴────┴────┘

Task1 (10ms):     ████          ████          ████
Task2 (5ms):      ████    ████    ████    ████    ████
Task3 (100ms):    ████                                    (未显示)
```

---

### 六、任务分组策略

#### 6.1 按周期分组（推荐）

```c
while (1) {
    uint32_t now = HAL_GetTick();

    // 高频任务：5ms
    if (now - last_5ms >= 5) {
        last_5ms = now;
        IMU_Task();            // 姿态解算需要高频
    }

    // 中频任务：10ms
    if (now - last_10ms >= 10) {
        last_10ms = now;
        Encoder_Task();        // 编码器采样
        PID_Task();            // PID 控制
        Odom_Task();           // 里程计更新
    }

    // 低频任务：50ms
    if (now - last_50ms >= 50) {
        last_50ms = now;
        Gray_Task();           // 灰度扫描
        Trace_Task();          // 巡线控制
    }

    // 超低频任务：200ms
    if (now - last_200ms >= 200) {
        last_200ms = now;
        LED_Toggle();          // 心跳灯
    }

    // 无周期限制：每次循环都执行
    CLI_Process();             // 命令行处理
}
```

#### 6.2 为什么这样分组？

| 任务 | 周期 | 原因 |
|------|------|------|
| **IMU** | 5ms | 姿态解算需要高频更新，否则积分漂移 |
| **编码器+PID** | 10ms | 电机控制需要稳定周期 |
| **灰度+巡线** | 50ms | 传感器响应慢，不需要太频繁 |
| **LED** | 200ms | 人眼看不到太快的闪烁 |

---

### 七、代码实现模板

```c
// ============================================
// 调度器头文件 scheduler.h
// ============================================
#ifndef __SCHEDULER_H
#define __SCHEDULER_H

#include "stm32f4xx_hal.h"

// 任务周期定义 (ms)
#define TASK_PERIOD_1MS     1
#define TASK_PERIOD_5MS     5
#define TASK_PERIOD_10MS    10
#define TASK_PERIOD_50MS    50
#define TASK_PERIOD_100MS   100
#define TASK_PERIOD_200MS   200

// 任务回调函数类型
typedef void (*TaskCallback_t)(void);

// 任务结构体
typedef struct {
    TaskCallback_t  callback;       // 任务函数
    uint32_t        period_ms;      // 执行周期
    uint32_t        last_tick;      // 上次执行时间
    uint8_t         enabled;        // 使能标志
} Task_t;

// API
void Scheduler_Init(void);
void Scheduler_AddTask(TaskCallback_t cb, uint32_t period_ms);
void Scheduler_Run(void);

#endif

// ============================================
// 调度器源文件 scheduler.c
// ============================================
#include "scheduler.h"

#define MAX_TASKS   16

static Task_t s_tasks[MAX_TASKS];
static uint8_t s_task_count = 0;

void Scheduler_Init(void) {
    s_task_count = 0;
    memset(s_tasks, 0, sizeof(s_tasks));
}

void Scheduler_AddTask(TaskCallback_t cb, uint32_t period_ms) {
    if (s_task_count >= MAX_TASKS || cb == NULL) return;

    s_tasks[s_task_count].callback = cb;
    s_tasks[s_task_count].period_ms = period_ms;
    s_tasks[s_task_count].last_tick = 0;
    s_tasks[s_task_count].enabled = 1;
    s_task_count++;
}

void Scheduler_Run(void) {
    uint32_t now = HAL_GetTick();

    for (uint8_t i = 0; i < s_task_count; i++) {
        Task_t *task = &s_tasks[i];

        if (!task->enabled) continue;

        if (now - task->last_tick >= task->period_ms) {
            task->last_tick = now;
            task->callback();  // 执行任务
        }
    }
}
```

---

### 八、使用示例

```c
// ============================================
// main.c
// ============================================
#include "scheduler.h"
#include "DX_common_headfile.h"

// 任务函数
void Task_10ms_Encoder_PID(void) {
    DX_Encoder_Task();
    DX_PID_Task();
    DX_Odom_Task();
}

void Task_5ms_IMU(void) {
    DX_IMU_Task();
}

void Task_50ms_Gray_Trace(void) {
    DX_Gray_Task();
    DX_Chassis_Task();
    DX_Trace_Task();
}

void Task_200ms_LED(void) {
    DX_LED_Toggle();
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    // ... 外设初始化 ...

    // BSP 初始化
    DX_LED_Init();
    DX_Motor_Init();
    DX_Encoder_Init();
    DX_PID_Init();
    DX_IMU_Init();
    DX_Gray_Init();
    DX_Trace_Init();

    // 初始化调度器
    Scheduler_Init();

    // 注册任务
    Scheduler_AddTask(Task_5ms_IMU, 5);
    Scheduler_AddTask(Task_10ms_Encoder_PID, 10);
    Scheduler_AddTask(Task_50ms_Gray_Trace, 50);
    Scheduler_AddTask(Task_200ms_LED, 200);

    printf("System ready\r\n");

    // 主循环
    while (1) {
        Scheduler_Run();     // 执行调度器
        DX_CLI_Process();    // 命令行处理（无周期限制）
        IWDG_Feed();         // 喂狗
    }
}
