```c
// ============================================
// 调度器头文件 scheduler.h
// ============================================
#ifndef __SCHEDULER_H
#define __SCHEDULER_H

#include "stm32f4xx_hal.h"

// 任务周期定义 (ms)
#define TASK_PERIOD_1MS     1
#define TASK_PERIOD_5MS     5
#define TASK_PERIOD_10MS    10
#define TASK_PERIOD_50MS    50
#define TASK_PERIOD_100MS   100
#define TASK_PERIOD_200MS   200

// 任务回调函数类型
typedef void (*TaskCallback_t)(void);

// 任务结构体
typedef struct {
    TaskCallback_t  callback;       // 任务函数
    uint32_t        period_ms;      // 执行周期
    uint32_t        last_tick;      // 上次执行时间
    uint8_t         enabled;        // 使能标志
} Task_t;

// API
void Scheduler_Init(void);
void Scheduler_AddTask(TaskCallback_t cb, uint32_t period_ms);
void Scheduler_Run(void);

#endif

// ============================================
// 调度器源文件 scheduler.c
// ============================================
#include "scheduler.h"

#define MAX_TASKS   16

static Task_t s_tasks[MAX_TASKS];
static uint8_t s_task_count = 0;

void Scheduler_Init(void) {
    s_task_count = 0;
    memset(s_tasks, 0, sizeof(s_tasks));
}

void Scheduler_AddTask(TaskCallback_t cb, uint32_t period_ms) {
    if (s_task_count >= MAX_TASKS || cb == NULL) return;

    s_tasks[s_task_count].callback = cb;
    s_tasks[s_task_count].period_ms = period_ms;
    s_tasks[s_task_count].last_tick = 0;
    s_tasks[s_task_count].enabled = 1;
    s_task_count++;
}

void Scheduler_Run(void) {
    uint32_t now = HAL_GetTick();

    for (uint8_t i = 0; i < s_task_count; i++) {
        Task_t *task = &s_tasks[i];

        if (!task->enabled) continue;

        if (now - task->last_tick >= task->period_ms) {
            task->last_tick = now;
            task->callback();  // 执行任务
        }
    }
}
```

