void Scheduler_AddTask(TaskCallback_t cb, uint32_t period_ms);
void Scheduler_Run(void);

#endif

// ============================================
// 调度器源文件 scheduler.c
// ============================================
#include "scheduler.h"

#define MAX_TASKS   16

static Task_t s_tasks[MAX_TASKS];
static uint8_t s_task_count = 0;

void Scheduler_Init(void) {
    s_task_count = 0;
    memset(s_tasks, 0, sizeof(s_tasks));
}

void Scheduler_AddTask(TaskCallback_t cb, uint32_t period_ms) {
    if (s_task_count >= MAX_TASKS || cb == NULL) return;

    s_tasks[s_task_count].callback = cb;
    s_tasks[s_task_count].period_ms = period_ms;
    s_tasks[s_task_count].last_tick = 0;
    s_tasks[s_task_count].enabled = 1;
    s_task_count++;
}

void Scheduler_Run(void) {
    uint32_t now = HAL_GetTick();

    for (uint8_t i = 0; i < s_task_count; i++) {
        Task_t *task = &s_tasks[i];

        if (!task->enabled) continue;

        if (now - task->last_tick >= task->period_ms) {
            task->last_tick = now;
            task->callback();  // 执行任务
        }
    }
}
```

