    TASK_STATE_READY = 0,   // 就绪态
    TASK_STATE_RUNNING,     // 运行态
    TASK_STATE_BLOCKED,     // 阻塞态 (等待延时)
    TASK_STATE_SUSPENDED,   // 挂起态 (手动挂起)
} TaskState_t;

/* 任务优先级 */
typedef enum {
    TASK_PRIORITY_IDLE = 0, // 空闲优先级
    TASK_PRIORITY_LOW,      // 低优先级
    TASK_PRIORITY_NORMAL,   // 正常优先级
    TASK_PRIORITY_HIGH,     // 高优先级
    TASK_PRIORITY_URGENT,   // 紧急优先级
} TaskPriority_t;

/* 任务控制块 (TCB) */
typedef struct {
    void            (*task_func)(void *param);  // 任务函数
    void            *param;                     // 任务参数
    TaskState_t     state;                      // 任务状态
    TaskPriority_t  priority;                   // 任务优先级
    uint32_t        delay_ticks;                // 剩余延时节拍数
    uint32_t        stack[TASK_STACK_SIZE/4];   // 任务栈
    char            name[16];                   // 任务名称
} TaskControlBlock_t;

