typedef struct {
    void            (*task_func)(void *param);  // 任务函数
    void            *param;                     // 任务参数
    TaskState_t     state;                      // 任务状态
    TaskPriority_t  priority;                   // 任务优先级
    uint32_t        delay_ticks;                // 剩余延时节拍数
    uint32_t        stack[TASK_STACK_SIZE/4];   // 任务栈
    char            name[16];                   // 任务名称
} TaskControlBlock_t;

/* API 函数 */
void RTOS_Init(void);
bool RTOS_CreateTask(void (*task_func)(void *param), 
                     const char *name,
                     TaskPriority_t priority,
                     void *param);
void RTOS_Delay(uint32_t ms);
void RTOS_SuspendTask(const char *name);
void RTOS_ResumeTask(const char *name);
void RTOS_Start(void);
void RTOS_Schedule(void);
uint32_t RTOS_GetTickCount(void);

#endif /* __MINI_RTOS_H */
```

### 3.2 源文件 `mini_rtos.c`

```c
/**
 * @file    mini_rtos.c
 * @brief   简化版 RTOS 调度器实现
 *          使用协作式调度 + 优先级抢占
 */

#include "mini_rtos.h"
#include <string.h>

/* 任务列表 */
static TaskControlBlock_t s_tasks[MAX_TASKS];
static uint8_t s_task_count = 0;

/* 当前运行的任务 */
static int8_t s_current_task = -1;

/* 系统时钟计数 */
static uint32_t s_tick_count = 0;

/* 调度器是否运行 */
static bool s_scheduler_running = false;

/* 空闲任务 */
static void Idle_Task(void *param);

/**
 * @brief  初始化 RTOS
 */
void RTOS_Init(void) {
    s_task_count = 0;
    s_current_task = -1;
    s_tick_count = 0;
    s_scheduler_running = false;
    memset(s_tasks, 0, sizeof(s_tasks));

    // 创建空闲任务
    RTOS_CreateTask(Idle_Task, "IDLE", TASK_PRIORITY_IDLE, NULL);
}

/**
 * @brief  创建任务
 * @param  task_func : 任务函数
 * @param  name      : 任务名称
 * @param  priority  : 优先级
 * @param  param     : 任务参数
 * @retval true=成功, false=失败
 */
bool RTOS_CreateTask(void (*task_func)(void *param), 
                     const char *name,
                     TaskPriority_t priority,
                     void *param) {
    if (s_task_count >= MAX_TASKS || task_func == NULL) {
        return false;
    }

    TaskControlBlock_t *tcb = &s_tasks[s_task_count];

    tcb->task_func = task_func;
    tcb->param = param;
    tcb->state = TASK_STATE_READY;
    tcb->priority = priority;
    tcb->delay_ticks = 0;

    // 复制任务名称
    if (name != NULL) {
        strncpy(tcb->name, name, sizeof(tcb->name) - 1);
    }

    s_task_count++;

    printf("[RTOS] Created task: %s (priority=%d)\r\n", name, priority);
    return true;
}

/**
 * @brief  延时函数 (让出 CPU)
 * @param  ms : 延时毫秒数
 */
void RTOS_Delay(uint32_t ms) {
    if (s_current_task >= 0 && s_current_task < s_task_count) {
        s_tasks[s_current_task].delay_ticks = ms / TICK_RATE_MS;
        s_tasks[s_current_task].state = TASK_STATE_BLOCKED;

        // 触发调度 (在实际 RTOS 中，这里会调用 PendSV 切换任务)
        // 在我们的简化版本中，直接返回让调度器处理
    }
}

/**
 * @brief  挂起任务
 * @param  name : 任务名称
 */
void RTOS_SuspendTask(const char *name) {
    for (uint8_t i = 0; i < s_task_count; i++) {
        if (strcmp(s_tasks[i].name, name) == 0) {
            s_tasks[i].state = TASK_STATE_SUSPENDED;
            printf("[RTOS] Suspended task: %s\r\n", name);
            return;
        }
    }
}

/**
 * @brief  恢复任务
 * @param  name : 任务名称
 */
void RTOS_ResumeTask(const char *name) {
    for (uint8_t i = 0; i < s_task_count; i++) {
        if (strcmp(s_tasks[i].name, name) == 0) {
            if (s_tasks[i].state == TASK_STATE_SUSPENDED) {
                s_tasks[i].state = TASK_STATE_READY;
                printf("[RTOS] Resumed task: %s\r\n", name);
            }
            return;
        }
    }
}

/**
 * @brief  获取系统时钟
 * @retval 毫秒数
 */
uint32_t RTOS_GetTickCount(void) {
    return s_tick_count;
}

/**
 * @brief  选择下一个要运行的任务 (基于优先级)
 * @retval 任务索引, -1=无就绪任务
 */
static int8_t RTOS_SelectNextTask(void) {
    int8_t highest_priority = -1;
    int8_t selected_task = -1;

    // 找到优先级最高的就绪任务
    for (uint8_t i = 0; i < s_task_count; i++) {
        if (s_tasks[i].state == TASK_STATE_READY) {
            if ((int8_t)s_tasks[i].priority > highest_priority) {
                highest_priority = (int8_t)s_tasks[i].priority;
                selected_task = i;
            }
        }
    }

    return selected_task;
}

/**
 * @brief  更新任务延时
 *        在系统时钟中断中调用 (每 1ms)
 */
static void RTOS_UpdateDelays(void) {
    s_tick_count++;

    for (uint8_t i = 0; i < s_task_count; i++) {
        if (s_tasks[i].state == TASK_STATE_BLOCKED) {
            if (s_tasks[i].delay_ticks > 0) {
                s_tasks[i].delay_ticks--;

                // 延时到期，恢复就绪态
                if (s_tasks[i].delay_ticks == 0) {
                    s_tasks[i].state = TASK_STATE_READY;
                }
            }
        }
    }
}

/**
 * @brief  调度器 (协作式)
 *        主循环中调用
 */
void RTOS_Schedule(void) {
    if (!s_scheduler_running) return;

    // 更新延时
    RTOS_UpdateDelays();

    // 选择下一个任务
    int8_t next_task = RTOS_SelectNextTask();

    if (next_task >= 0) {
        // 切换任务
        s_current_task = next_task;
        s_tasks[s_current_task].state = TASK_STATE_RUNNING;

        // 执行任务
        s_tasks[s_current_task].task_func(s_tasks[s_current_task].param);

        // 任务执行完毕，恢复就绪态
        // (如果任务内部调用了 RTOS_Delay，状态会变成 BLOCKED)
        if (s_tasks[s_current_task].state == TASK_STATE_RUNNING) {
            s_tasks[s_current_task].state = TASK_STATE_READY;
        }

        s_current_task = -1;
    }
}

/**
 * @brief  启动调度器
 */
void RTOS_Start(void) {
    printf("[RTOS] Scheduler started with %d tasks\r\n", s_task_count);
    s_scheduler_running = true;

    // 主循环
    while (1) {
        RTOS_Schedule();
    }
}

/**
 * @brief  空闲任务
 */
static void Idle_Task(void *param) {
    // 空闲任务：喂狗、低功耗等
    (void)param;

    // 这里可以进入低功耗模式
    // __WFI();  // Wait For Interrupt
}

/**
 * @brief  SysTick 中断处理 (1ms)
 *        需要在 stm32f4xx_it.c 中调用
 */
void RTOS_SysTick_Handler(void) {
    RTOS_UpdateDelays();
}
