## 四、使用示例

```c
/**
 * @file    main.c
 * @brief   使用简化版 RTOS 的示例
 */

#include "mini_rtos.h"
#include "DX_common_headfile.h"

/* 任务函数 */
void Task_MotorControl(void *param) {
    (void)param;

    while (1) {
        DX_Encoder_Task();
        DX_PID_Task();
        DX_Odom_Task();

        RTOS_Delay(10);  // 延时 10ms，让出 CPU
    }
}

void Task_IMU(void *param) {
    (void)param;

    while (1) {
        DX_IMU_Task();

        RTOS_Delay(5);   // 延时 5ms，让出 CPU
    }
}

void Task_Grayscale(void *param) {
    (void)param;

    while (1) {
        DX_Gray_Task();
        DX_Chassis_Task();
        DX_Trace_Task();

        RTOS_Delay(50);  // 延时 50ms，让出 CPU
    }
}

void Task_CLI(void *param) {
    (void)param;

    while (1) {
        DX_CLI_Process();

        RTOS_Delay(10);  // 延时 10ms，让出 CPU
    }
}

void Task_Heartbeat(void *param) {
    (void)param;

    while (1) {
        DX_LED_Toggle();
        printf("System tick: %lu\r\n", RTOS_GetTickCount());

        RTOS_Delay(500); // 延时 500ms，让出 CPU
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();

    // CubeMX 外设初始化
    MX_GPIO_Init();
    MX_I2C2_Init();
    MX_TIM1_Init();
    MX_USART1_UART_Init();

    // BSP 初始化
    DX_Debug_Init();
    DX_LED_Init();
    DX_Motor_Init();
    DX_Encoder_Init();
    DX_PID_Init();
    DX_IMU_Init();
    DX_Gray_Init();
    DX_Trace_Init();

    // RTOS 初始化
    RTOS_Init();

    // 创建任务
    RTOS_CreateTask(Task_MotorControl, "MOTOR",   TASK_PRIORITY_HIGH,   NULL);
    RTOS_CreateTask(Task_IMU,          "IMU",     TASK_PRIORITY_HIGH,   NULL);
    RTOS_CreateTask(Task_Grayscale,    "GRAY",    TASK_PRIORITY_NORMAL, NULL);
    RTOS_CreateTask(Task_CLI,          "CLI",     TASK_PRIORITY_LOW,    NULL);
    RTOS_CreateTask(Task_Heartbeat,    "HEART",   TASK_PRIORITY_LOW,    NULL);

    printf("System ready, starting RTOS...\r\n");

    // 启动调度器 (不会返回)
    RTOS_Start();

    // 永远不会执行到这里
    while (1) {}
}
